window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[277]={"id":"277","numero":277,"titre":"Lithiase biliaire et complications","objectifs":[{"id":"277-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une lithiase biliaire et des différentes complications","contenu":"<div class=\"notion-course\"><p>La <strong><span>lithiase biliaire</span></strong> désigne la présence de <span>calculs</span> formés à partir de la bile. La <span><span class=\"nc-blue_bg\">lithiase vésiculaire</span></span> (calcul dans la <span>vésicule</span>) est la forme la plus fréquente ; elle est <strong><span class=\"nc-orange nc-bold\">asymptomatique</span> dans <span>80 %</span></strong> des cas. <span>Les</span> manifestations symptomatiques et compliquées découlent de la mobilisation <span class=\"nc-yellow_bg\">d’un calcul</span> et de son <span class=\"nc-yellow_bg\">blocage</span> à différents niveaux de l’arbre biliaire.</p>\n      <table>\n        <thead><tr><th>Entité</th><th>Définition / mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span><span class=\"nc-blue_bg\">Lithiase vésiculaire</span></span></strong></td><td>Calcul formé à partir de la bile, localisé dans la <span>vésicule biliaire</span></td></tr>\n          <tr><td><strong><span><span class=\"nc-orange_bg\">Colique hépatique</span></span></strong></td><td>Douleur par mise en tension brutale des voies biliaires lors du <span class=\"nc-yellow_bg\">blocage</span> <span><span class=\"nc-yellow_bg nc-bold\">transitoire</span></span> <span class=\"nc-yellow_bg\">d’un calcul</span> (<span class=\"nc-purple nc-bold\">canal cystique</span> ou VBP)</td></tr>\n          <tr><td colspan=\"2\">Cholécystite aiguë : inflammation de la vésicule, habituellement sur obstruction du <span class=\"nc-purple nc-bold\">canal cystique</span> ; l’<span class=\"nc-red nc-bold\">infection</span> peut être secondaire, elle n’est pas indispensable à la définition.</td></tr>\n          <tr><td><strong><span>Lithiase de la VBP</span></strong></td><td>Calcul <span class=\"nc-red nc-bold\">dans la </span><span><span class=\"nc-red nc-bold\">voie biliaire principale</span></span> ; peut causer un <span><span class=\"nc-orange nc-bold\">ictère</span></span> si <span class=\"nc-purple_bg\">obstruction prolongée</span></td></tr>\n          <tr><td><strong><span>Angiocholite</span></strong></td><td><span>Infection bactérienne de la VBP</span> par enclavement d’un calcul au niveau de l’<span>ampoule de Vater</span></td></tr>\n          <tr><td><strong><span>Pancréatite aiguë</span></strong></td><td><span><span class=\"nc-red nc-bold\">Inflammation aiguë</span> du pancréas</span> par migration d’un calcul dans l’ampoule de Vater</td></tr>\n          <tr><td><strong><span>Iléus</span> biliaire</strong></td><td>Syndrome <span>occlusif</span> par obstruction duodénale/iléale par un calcul</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Repère.</strong> Le tableau de synthèse comparant douleur, <span>fièvre</span>, <span><span class=\"nc-orange nc-bold\">ictère</span></span>, biologie <span class=\"nc-blue_bg\">et écho</span> de chaque forme se trouve dans l’onglet <em>Astuces &amp; Pièges</em> (discriminant clé).</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/biliary-tree-anatomy","label":"Radiopaedia : Biliary tree anatomy"},{"href":"https://radiopaedia.org/articles/gallstones-1","label":"Radiopaedia : Gallstones 1"},{"href":"https://radiopaedia.org/articles/acute-cholecystitis","label":"Radiopaedia : Acute cholecystitis"},{"href":"https://radiopaedia.org/articles/pancreatitis","label":"Radiopaedia : Pancreatitis"}]},{"id":"277-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l’incidence de la pathologie lithiasique biliaire, la fréquence de survenue de symptômes et les indications de dépistage.","contenu":"<div class=\"notion-course\"><p>La <span><span class=\"nc-blue_bg\">lithiase vésiculaire</span></span> touche <span>20 %</span> de la population générale, et jusqu’à <span><span class=\"nc-pink nc-bold\">60 %</span></span><span class=\"nc-pink nc-bold\"> à </span><span><span class=\"nc-pink nc-bold\">80 ans</span></span> (<span>prévalence croissante avec l’âge</span>).</p>\n      <ul>\n        <li><span>Asymptomatique</span> dans <span>80 %</span> des cas</li>\n        <li><span>Symptomatique</span> dans <span>20 %</span> des cas</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong><span><span class=\"nc-green nc-bold\">Dépistage</span></span>.</strong> Le <span class=\"nc-green nc-bold\">dépistage</span> de la <span><span class=\"nc-blue_bg\">lithiase vésiculaire</span></span> <span>n’est PAS indiqué</span> chez le sujet <span class=\"nc-orange nc-bold\">asymptomatique</span>.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":0},{"id":"277-3","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la fréquence des complications de la lithiase biliaire","contenu":"<div class=\"notion-course\"><p>Parmi <span>les</span> sujets <span>symptomatiques</span>, la probabilité cumulée de complication est faible : <span>5 %</span> des sujets symptomatiques développent une complication (<span>cholécystite</span>, <span>migration</span>, <span>angiocholite</span>, <span>pancréatite</span>).</p>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> La grande majorité des <span>lithiases vésiculaires</span> reste <span>silencieuse</span> ; le risque évolutif ne concerne qu’une minorité de patients devenus symptomatiques.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":0},{"id":"277-4","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les caractéristiques des calculs et les facteurs de risque de calculs cholestéroliques et pigmentaires","contenu":"<div class=\"notion-course\"><p>Deux grands types de calculs, de fréquence et de mécanisme distincts :</p>\n      <table>\n        <thead><tr><th></th><th>Calculs cholestéroliques</th><th>Lithiase p<span>igm</span>entaire</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Fréquence</strong></td><td><span>80 %</span></td><td><span>20 %</span></td></tr>\n          <tr>\n            <td><strong>Mécanisme</strong></td>\n            <td>Augmentation de la concentration biliaire en <span>cholestérol</span> ; sursaturation → nucléation → précipitation</td>\n            <td><span>Déconjugaison de la bilirubine</span> qui devient insoluble (la <span>bilirubine</span> conjuguée est soluble, la non-conjuguée est insoluble)</td>\n          </tr>\n          <tr>\n            <td><strong><span>Facteurs de risque</span></strong></td>\n            <td>\n              <strong>Âge :</strong> <span><span class=\"nc-pink nc-bold\">&gt; 50-65 ans</span></span> ; <span>ATCD familiaux</span><br>\n              <strong>Femme :</strong> <span><span class=\"nc-pink_bg\">sexe féminin</span></span> ; <span><span class=\"nc-pink_bg\">multiparité</span></span> ; <span><span class=\"nc-pink_bg\">grossesse</span></span><br>\n              <strong>Pondéral :</strong> <span><span class=\"nc-orange_bg\">surpoids/obésité</span></span> ; <span>variations importantes de poids</span><br>\n              <strong>Digestif :</strong> <span><span class=\"nc-blue_bg\">jeûne prolongé</span></span> ; <span><span class=\"nc-blue_bg\">nutrition parentérale</span></span> ; ATCD de <span>gastrectomie ou bypass</span><br>\n              <strong>Médicaments :</strong> <span>œstrogènes</span> ; <span><span class=\"nc-pink nc-bold\">fibrates</span></span> ; <span>analogues de la somatostatine</span>\n            </td>\n            <td>\n              <strong><span class=\"nc-orange_bg\">Hémolyse</span> :</strong> <span><span class=\"nc-orange_bg\">drépanocytose</span></span> ; <span><span class=\"nc-orange_bg\">thalassémie</span></span> (augmentation de la production de <span>bilirubine</span>)<br>\n              <strong><span>Infectieux</span> :</strong> <span><span class=\"nc-red_bg\">infections biliaires chroniques</span></span><br>\n              <strong>Obstacle :</strong> <span>sténose bénigne/maligne de la VBP</span>\n            </td>\n          </tr>\n        </tbody>\n      </table></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":1},{"id":"277-7","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les trois complications de la pathologie lithiasique vésiculaire et leur mécanisme","contenu":"<div class=\"notion-course\"><p><span class=\"nc-red nc-bold\">Trois complications</span> principales selon le niveau et la durée du blocage :</p>\n      <table>\n        <thead><tr><th>Complication</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-orange_bg\">Colique hépatique</span></span></td><td><span class=\"nc-yellow_bg\">Blocage</span> <span><span class=\"nc-yellow_bg nc-bold\">transitoire</span></span> <span class=\"nc-yellow_bg\">d’un calcul</span> (<span class=\"nc-purple nc-bold\">canal cystique</span> ou VBP) → <span>mise en tension brutale des voies biliaires</span></td></tr>\n          <tr><td><span>Cholécystite aiguë</span></td><td><span><span class=\"nc-red nc-bold\">Obstruction prolongée du canal cystique</span></span> → inflammation puis <span>infection</span> de la <span>vésicule</span></td></tr>\n          <tr><td><span>Migration lithiasique</span> (vers la VBP)</td><td>Passage d’un <span class=\"nc-blue_bg\">calcul dans la VBP</span> → peut se compliquer de <span>lithiase de la VBP</span>, <span>angiocholite</span> ou <span>pancréatite aiguë</span></td></tr>\n        </tbody>\n      </table></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":1},{"id":"277-8","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie de la lithiase cholestérolique et de la lithiase pigmentaire","contenu":"<div class=\"notion-course\"><table>\n        <thead><tr><th>Type</th><th><span>Physiopathologie</span></th></tr></thead>\n        <tbody>\n          <tr><td><span>Lithiase cholestérolique</span></td><td>Augmentation de la concentration biliaire en <span>cholestérol</span> (causée par <span>les</span> FR) → <span>sursaturation</span> → <span>nucléation</span> → <span>précipitation lithiasique</span></td></tr>\n          <tr><td><span>Lithiase pigmentaire</span></td><td><span>Déconjugaison de la bilirubine</span> qui devient insoluble : la <span>bilirubine conjuguée est soluble, la non-conjuguée est insoluble</span> → précipitation</td></tr>\n        </tbody>\n      </table></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":0},{"id":"277-9","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les caractéristiques de la douleur biliaire","contenu":"<div class=\"notion-course\"><p>La <strong><span><span class=\"nc-orange_bg\">colique hépatique</span></span></strong> est la traduction douloureuse du <span class=\"nc-yellow_bg\">blocage</span> <span class=\"nc-yellow_bg nc-bold\">transitoire</span> <span class=\"nc-yellow_bg\">d’un calcul</span>. Ses caractéristiques sémiologiques :</p>\n      <table>\n        <thead><tr><th>Caractéristique</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Type</strong></td><td><span>brutale, intense</span></td></tr>\n          <tr><td><strong>Intensité</strong></td><td>Continue, à type de <span><span class=\"nc-orange nc-bold\">broiement</span></span> ou <span><span class=\"nc-orange nc-bold\">crampe</span></span></td></tr>\n          <tr><td><strong>Localisation</strong></td><td><span>épigastrique</span> ou <span>hypochondre droit</span></td></tr>\n          <tr><td><strong>Durée</strong></td><td><span>&lt; 6 h</span></td></tr>\n          <tr><td><strong><span>Irradiation</span></strong></td><td>Hémi-ceinture → <span>épaule / omoplate</span></td></tr>\n          <tr><td><strong>Signes associés</strong></td><td><span><span class=\"nc-pink nc-bold\">inhibition de la respiration</span></span> ; <span>nausées</span>, vomissements</td></tr>\n          <tr><td><strong>Signe spécifique</strong></td><td><span>signe de <span class=\"nc-green nc-bold\">Murphy</span></span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"nc-red_bg\">Signe négatif</span> capital.</strong> Une <span><span class=\"nc-orange_bg\">colique hépatique</span></span> simple ne comporte <span><span class=\"nc-red nc-bold\">JAMAIS</span> de <span class=\"nc-red\">fièvre</span> ni d’<span class=\"nc-red\">ictère</span></span> — leur présence signe une complication (<span>cholécystite</span>, angiocholite).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 269 — Douleur abdominale aiguë</em></p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Un signe de <span class=\"nc-green nc-bold\">Murphy</span> évoque surtout une inflammation vésiculaire ; sa présence ne suffit pas à caractériser une <span class=\"nc-orange_bg\">colique hépatique</span> simple. Une paroi épaissie n’est pas spécifique et s’interprète avec douleur, <span class=\"nc-red\">fièvre</span> et imagerie.</li></ul></div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":0},{"id":"277-10","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les trois principaux diagnostics différentiels à évoquer devant une colique hépatique","contenu":"<div class=\"notion-course\"><p>Devant une <span>douleur épigastrique / de l’hypochondre droit</span>, trois <span class=\"nc-pink nc-bold\">diagnostics différentiels</span> principaux à éliminer :</p>\n      <ul>\n        <li><span>SCA</span> (<span>syndrome coronarien aigu</span>) — surtout en cas de <span>douleur épigastrique trompeuse</span></li>\n        <li><span>UGD</span> (<span>ulcère gastro-duodénal</span>)</li>\n        <li><span>Pancréatite aiguë</span></li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 339 — <span>Syndrome coronarien</span> aiguë · 272 — Ulcère gastroduodénal - <span>gastrite</span> · 358 — <span>Pancréatite aiguë</span></em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":0},{"id":"277-11","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments du diagnostic positif de la lithiase vésiculaire symptomatique simple","contenu":"<div class=\"notion-course\"><p>Le diagnostic de <span><span class=\"nc-blue_bg\">lithiase vésiculaire</span></span> symptomatique simple repose sur un faisceau clinico-<span>biologique</span>-échographique :</p>\n      <table>\n        <thead><tr><th>Axe</th><th>Éléments</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Clinique</strong></td><td><span><span class=\"nc-orange_bg\">Colique hépatique</span></span> <span>&lt; 6 h</span> ; <span>pas de <span class=\"nc-red\">fièvre</span></span> ; <span><span class=\"nc-green_bg\">pas d’ictère</span></span> ; signe de <span><span class=\"nc-green nc-bold\">Murphy</span></span></td></tr>\n          <tr><td><strong>Biologie</strong></td><td>Aucune anomalie : <span><span class=\"nc-green_bg\">bilan hépatique normal</span></span> ; <span>pas de <span class=\"nc-blue_bg\">syndrome inflammatoire</span></span> (sauf si <span class=\"nc-red nc-bold\">migration lithiasique</span> associée)</td></tr>\n          <tr><td><strong><span>Échographie</span></strong></td><td>Calculs vésiculaires : <span>hyperéchogènes</span> ; <span>cône d’ombre postérieur</span> ; <span>mobiles</span> avec le patient (<span>Se 95 %</span>, meilleure que <span>TDM</span>/<span>IRM</span>). Ne pas confondre avec le <span>sludge</span> (bile épaisse)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> Le <span>sludge</span> (boue biliaire) est hyperéchogène mais SANS cône d’ombre et déclive — à ne pas prendre pour un calcul.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":3},{"id":"277-12","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes du traitement de la pathologie lithiasique symptomatique","contenu":"<div class=\"notion-course\"><p>Deux volets : soulager la crise, puis prévenir la récidive.</p>\n      <ul>\n        <li><strong>Traitement de la crise</strong> (en <span><span class=\"nc-green_bg\">urgence</span></span>, <span class=\"nc-green_bg\">voie</span> <strong><span class=\"nc-green_bg\">parentérale</span></strong>) :\n          <span>antispasmodiques</span> (<span><span class=\"nc-pink nc-bold\">phloroglucinol</span></span> ou <span><span class=\"nc-pink nc-bold\">trimébutine</span></span>) ; <span>antalgiques</span> ± <span>AINS</span> <span>en l’absence de contre-indication</span></li>\n        <li><strong><span><span class=\"nc-pink nc-bold\">Cholécystectomie</span></span></strong> (sous cœlioscopie de préférence) pour éviter récidive/complication, réalisée rapidement une fois la crise calmée (<span><span class=\"nc-red nc-bold\">&lt; 1 mois</span></span>)</li>\n      </ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":1},{"id":"277-13","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître l’indication des examens d’imagerie devant une lithiase biliaire","contenu":"<div class=\"notion-course\"><p>L’examen de <strong><span><span class=\"nc-red nc-bold\">1ʳᵉ intention</span></span></strong> devant une <span class=\"nc-pink nc-bold\">lithiase biliaire symptomatique</span> est <span class=\"nc-blue nc-bold\">l’</span><strong><span><span class=\"nc-blue nc-bold\">échographie abdominale</span></span></strong> (<span>Se 95 %</span> pour <span>les</span> calculs vésiculaires, <span>meilleure que <span class=\"nc-blue_bg nc-bold\">TDM</span>/IRM</span>).</p>\n      <p>Le <span><span class=\"nc-blue_bg\">scanner abdominal</span></span> ou la <span><span class=\"nc-blue_bg\">bili-IRM</span></span> sont discutés en <span><span class=\"nc-red_bg nc-bold\">2ᵉ intention</span></span> (calcul vésiculaire isolé : pas d’indication).</p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":2},{"id":"277-14","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître le mécanisme et savoir diagnostiquer une migration lithiasique","contenu":"<div class=\"notion-course\"><p><strong>Mécanisme :</strong> migration de petits calculs <span><span class=\"nc-red nc-bold\">dans la voie biliaire principale</span></span>, le plus souvent <span><span class=\"nc-yellow_bg nc-bold\">transitoire</span></span> (le calcul passe puis est évacué).</p>\n      <p><strong>Diagnostic :</strong></p>\n      <ul>\n        <li><span class=\"nc-blue_bg\">Élévation </span><span><span class=\"nc-blue_bg\">transitoire</span></span><span class=\"nc-blue_bg\"> des </span><span><span class=\"nc-blue_bg\">transaminases</span></span>, <span><span class=\"nc-blue nc-bold\">diminuant de &gt; 50 % en </span><span><span class=\"nc-blue nc-bold\">&lt; 48 h</span></span></span> (<span>bilirubine</span> et <span>γ-GT</span> normales)</li>\n        <li><span><span class=\"nc-brown_bg\">Échographie</span></span> : <span>parois vésiculaires fines</span>, <span>dilatation modérée ± inconstante de la VBP</span>, calcul rarement vu dans la VBP (écho souvent identique à une <span><span class=\"nc-orange_bg\">colique hépatique</span></span> simple)</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Discriminant.</strong> La <span>cinétique des <span class=\"nc-yellow nc-bold\">transaminases</span></span> (pic précoce qui s’effondre en <span><span class=\"nc-pink nc-bold\">&lt; 48 h</span></span>) est le meilleur signe de migration.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":0},{"id":"277-15","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître l’indication des examens d’imagerie devant une migration lithiasique","contenu":"<div class=\"notion-course\"><p><span class=\"nc-blue nc-bold\">L’</span><strong><span><span class=\"nc-blue nc-bold\">échographie</span></span></strong> est l’examen de <span><span class=\"nc-red nc-bold\">1ʳᵉ intention</span></span>, mais a une <span>mauvaise <span class=\"nc-pink nc-bold\">sensibilité</span></span> : elle met rarement en évidence la <span>dilatation de la VBP</span> ou le calcul cholédocien, et ne montre souvent que <span>les</span> calculs vésiculaires.</p>\n      <p>Le diagnostic repose donc <strong>essentiellement sur l’<span class=\"nc-blue_bg\">élévation transitoire des </span><span><span class=\"nc-blue_bg\">transaminases</span></span></strong>.</p>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> La <span><span class=\"nc-blue nc-bold\">bili-IRM</span></span> et l’<span><span class=\"nc-blue nc-bold\">écho-endoscopie</span></span> sont <span>les</span> meilleurs examens pour voir un calcul cholédocien, mais <span class=\"nc-red nc-bold\">ils ne sont </span><span><span class=\"nc-red nc-bold\">PAS utilisés en première intention</span></span>. Le <span><span class=\"nc-blue_bg nc-bold\">TDM</span></span> a <span class=\"nc-red_bg nc-bold\">une valeur diagnostique inférieure</span> pour les calculs de la VBP.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":0},{"id":"277-16","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir diagnostiquer une lithiase vésiculaire compliquée : cholécystite aiguë","contenu":"<div class=\"notion-course\"><p><strong>Mécanisme :</strong> <span class=\"nc-red nc-bold\">obstruction prolongée du canal cystique</span> → inflammation de la paroi vésiculaire puis <span><span class=\"nc-purple nc-bold\">infection aiguë</span></span> de la <span>vésicule</span>.</p>\n      <table>\n        <thead><tr><th>Axe</th><th>Éléments</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Clinique</strong></td><td><span><span class=\"nc-orange_bg\">Colique hépatique</span></span> persistante (<span>&gt; 6 h</span>, souvent <span>&gt; 24 h</span>) ; <span><span class=\"nc-blue_bg\">syndrome </span><span><span class=\"nc-blue_bg\">infectieux</span></span></span><span class=\"nc-blue_bg\"> fréquent (</span><span><span class=\"nc-blue_bg nc-bold\">fièvre</span></span><span class=\"nc-blue_bg\">, </span><span><span class=\"nc-blue_bg\">frissons</span></span><span class=\"nc-blue_bg\">)</span> ; <span><span class=\"nc-green_bg\">pas d’ictère</span></span> (sauf Mirizzi) ; signes d’irritation péritonéale possibles (<span>cholécystite</span> grave)</td></tr>\n          <tr><td><strong>Biologie</strong></td><td><span><span class=\"nc-blue_bg\">Syndrome inflammatoire</span></span> (hyperPNN, <span>CRP</span>/<span>PCT</span>) ; <span><span class=\"nc-green_bg\">bilan hépatique normal</span></span> ; <span><span class=\"nc-green_bg\">lipase normale</span></span></td></tr>\n          <tr><td><strong><span>Échographie</span></strong></td><td>Paroi vésiculaire <span><span class=\"nc-yellow_bg nc-bold\">&gt; 4 mm</span></span> en <span><span class=\"nc-red nc-bold\">triple</span> <span class=\"nc-red nc-bold\">feuillet</span></span> ; distension vésiculaire (&gt; <span>4 cm</span>) ; calcul vésiculaire (hyperéchogène, mobile, cône d’ombre) ; <span>Murphy échographique</span></td></tr>\n          <tr><td><strong>Microbiologie</strong></td><td><span>Hémocultures</span></td></tr>\n        </tbody>\n      </table></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":0},{"id":"277-17","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître l’indication des examens d’imagerie devant une cholécystite aiguë","contenu":"<div class=\"notion-course\"><p>L’examen de <strong><span><span class=\"nc-red nc-bold\">1ʳᵉ intention</span></span></strong> devant une <span><span class=\"nc-pink nc-bold\">cholécystite</span></span><span class=\"nc-pink nc-bold\"> aiguë</span> est <span class=\"nc-blue nc-bold\">l’</span><strong><span><span class=\"nc-blue nc-bold\">échographie abdominale</span></span></strong> (paroi <span><span class=\"nc-yellow_bg nc-bold\">&gt; 4 mm</span></span> en <span><span class=\"nc-red nc-bold\">triple</span> <span class=\"nc-red nc-bold\">feuillet</span></span>, distension <span>&gt; 4 cm</span>, <span>Murphy <span class=\"nc-blue nc-bold\">échographique</span></span>).</p>\n      <p>Le <span><span class=\"nc-blue_bg\">scanner abdominal</span></span> peut être discuté en <span><span class=\"nc-red_bg nc-bold\">2ᵉ intention</span></span> (doute diagnostique, complications, <span>contre-indication</span> chirurgicale).</p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":0},{"id":"277-18","rang":"B","rubrique":"Contenu multimédia","titre":"Bili-IRM d’un empierrement cholédocien","contenu":"<div class=\"notion-course\"><p>La <strong><span><span class=\"nc-blue nc-bold\">bili-IRM</span></span></strong> (<span class=\"nc-blue_bg\">cholangio-</span><span><span class=\"nc-blue_bg\">IRM</span></span>) est, avec l’<span><span class=\"nc-blue nc-bold\">écho-endoscopie</span></span>, le meilleur examen pour mettre en évidence des calculs de la <span class=\"nc-red nc-bold\">voie biliaire principale</span> (<span>Se &gt; 90 %</span>). Un <strong><span class=\"nc-red nc-bold\">empierrement cholédocien</span></strong> correspond à de <span>multiples calculs occupant la VBP</span>.</p>\n      <table>\n        <thead><tr><th>Élément sémiologique</th><th>Aspect <span>bili-IRM</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong>Voie biliaire principale</strong></td><td><span>Hypersignal T2</span> intense (la bile statique en T2 brille)</td></tr>\n          <tr><td><strong>Calculs cholédociens</strong></td><td><span>Images hypointenses en T2</span> (« defects ») au sein du conduit hypersignal — <span>absence de rehaussement</span> après injection</td></tr>\n          <tr><td><strong>Anatomie analysable</strong></td><td>Conduit hépatique droit, gauche, cystique, cholédoque — utile pour le bilan pré-<span>CPRE</span></td></tr>\n          <tr><td><strong>Empierrement</strong></td><td><span>Multiples defects</span> alignés dans la VBP, avec dilatation d’amont</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Mémo signal.</strong> En T2 : la <span>bile = blanche</span>, <span>les</span> <span>calculs = noirs</span>. Tout point noir dans un <span class=\"nc-yellow_bg nc-bold\">canal</span> blanc et dilaté = calcul jusqu’à preuve du contraire.</div>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/277/bili-irm-empierrement-choledocien.png\" alt=\"Bili-IRM (cholangio-IRM) chez deux patients : voie biliaire principale en hypersignal T2 contenant de multiples calculs hypointenses (defects) réalisant un empierrement cholédocien\" loading=\"lazy\">\n        <figcaption><span>Bili-IRM (cholangio-IRM)</span> — <span>empierrement cholédocien</span>. La <span>VBP en hypersignal T2</span> (bile blanche) contient de <span>multiples calculs hypointenses</span> (« defects » noirs) ; conduits hépatiques droit/gauche, cystique et cholédoque analysables. Source : banque « Imagerie à connaître » (item 277, p.66).</figcaption>\n      </figure></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":2},{"id":"277-19","rang":"B","rubrique":"Contenu multimédia","titre":"Aspect échographique d’une cholécystite aiguë","contenu":"<div class=\"notion-course\"><p><strong>Signes diagnostiques principaux</strong> (faisceau d’arguments) :</p>\n      <ul>\n        <li>Paroi vésiculaire <span>épaissie <span class=\"nc-yellow_bg nc-bold\">&gt; 4 mm</span></span>, aspect en <span><span class=\"nc-red nc-bold\">triple</span> <span class=\"nc-red nc-bold\">feuillet</span></span></li>\n        <li><span>Distension vésiculaire</span> (<span>&gt; 4 cm</span>)</li>\n        <li>Calcul vésiculaire <span>hyperéchogène</span>, mobile, avec <span>cône d’ombre postérieur</span></li>\n      </ul>\n      <p><strong>Autres signes</strong> (non indispensables au diagnostic, mais utiles) :</p>\n      <ul>\n        <li><span>Signe de <span class=\"nc-green nc-bold\">Murphy</span> échographique</span> — douleur au passage de la sonde sur la <span>vésicule</span></li>\n        <li><span>Sludge intra-vésiculaire</span> — bile épaisse hyperéchogène déclive, <span>sans cône d’ombre</span> (à distinguer du calcul)</li>\n        <li><span>Épanchement péri-vésiculaire</span> — <span>signe de gravité</span></li>\n      </ul>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/277/echo-cholecystite-aigue.png\" alt=\"Échographie hépato-biliaire chez deux patients : paroi vésiculaire épaissie en triple feuillet, distension, calcul intra-vésiculaire hyperéchogène avec cône d&#x27;ombre postérieur, sludge et épanchement péri-vésiculaire\" loading=\"lazy\">\n        <figcaption><span>Échographie hépato-biliaire</span> — <span>cholécystite aiguë lithiasique</span>. <span>Paroi vésiculaire épaissie &gt; 4 mm</span> en triple feuillet, <span>distension &gt; 4 cm</span>, <span>calcul hyperéchogène avec cône d'ombre postérieur</span> ; signes associés : sludge, épanchement péri-vésiculaire (gravité). Source : banque « Imagerie à connaître » (item 277, p.67).</figcaption>\n      </figure></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":0},{"id":"277-20","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes du traitement de la cholécystite aiguë","contenu":"<div class=\"notion-course\"><ul><li>Cholécystite aiguë lithiasique : hospitalisation, antalgiques, correction des troubles hydro-électrolytiques, antibiothérapie selon gravité et contexte, avis chirurgical.</li><li>La <span class=\"nc-pink nc-bold\">cholécystectomie</span> laparoscopique précoce au cours de la <span class=\"nc-pink nc-bold\">même hospitalisation</span> est privilégiée quand elle est réalisable. Dépasser 72 heures ne conduit pas automatiquement à attendre six semaines.</li><li>Défaillance d’organe ou risque opératoire élevé : réanimation et discussion multidisciplinaire du contrôle de foyer, parfois drainage vésiculaire. La durée d’antibiothérapie dépend de la complication et de l’efficacité du contrôle du foyer.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":0},{"id":"277-21","rang":"B","rubrique":"Prise en charge","titre":"Connaître le délai de prise en charge chirurgicale de la cholécystite","contenu":"<div class=\"notion-course\"><ul><li>Cholécystite aiguë lithiasique : hospitalisation, antalgiques, correction des troubles hydro-électrolytiques, antibiothérapie selon gravité et contexte, avis chirurgical.</li><li>La <span class=\"nc-pink nc-bold\">cholécystectomie</span> laparoscopique précoce au cours de la <span class=\"nc-pink nc-bold\">même hospitalisation</span> est privilégiée quand elle est réalisable. Dépasser 72 heures ne conduit pas automatiquement à attendre six semaines.</li><li>Défaillance d’organe ou risque opératoire élevé : réanimation et discussion multidisciplinaire du contrôle de foyer, parfois drainage vésiculaire. La durée d’antibiothérapie dépend de la complication et de l’efficacité du contrôle du foyer.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":0},{"id":"277-22","rang":"A","rubrique":"Suivi et / ou pronostic","titre":"Connaître les complications septiques de la cholécystite aiguë","contenu":"<div class=\"notion-course\"><p><span class=\"nc-purple nc-bold\">Complications septiques</span> de la <span><span class=\"nc-red nc-bold\">cholécystite</span></span><span class=\"nc-red nc-bold\"> aiguë</span> — <strong>par ordre chronologique d’aggravation</strong> :</p>\n      <ol>\n        <li><strong><span>Empyème vésiculaire</span></strong> (pyocholécyste) — <span>vésicule</span> sous tension remplie de pus, encore contenue par la paroi</li>\n        <li><strong><span>Gangrène vésiculaire</span></strong> — <span>nécrose</span> de la paroi vésiculaire (signe d’ischémie)</li>\n        <li><strong><span>Perforation</span></strong> de la paroi → <span>abcès péri-vésiculaire</span> ou <span><span class=\"nc-red_bg\">abcès hépatique</span></span> de contiguïté</li>\n        <li><strong><span><span class=\"nc-red nc-bold\">Péritonite biliaire</span></span></strong> — diffusion au péritoine, localisée puis généralisée (<span>urgence</span> chirurgicale absolue)</li>\n      </ol>\n      <div class=\"callout callout-info\"><strong>Pour mémoire (hors référentiel).</strong> <span>Iléus biliaire</span> (occlusion <span class=\"nc-green_bg\">par</span> <span><span class=\"nc-red_bg\">fistule bilio-digestive</span></span>, <span>terrain</span> âgé) et <span>syndrome de Mirizzi</span> (gros calcul du <span class=\"nc-yellow_bg nc-bold\">collet</span> comprimant la VBP → <span>cholécystite + <span class=\"nc-yellow_bg\">ictère</span></span>) sont des <span class=\"nc-red nc-bold\">complications</span> plus rares.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 357 — <span>Péritonite</span> aiguë</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":0},{"id":"277-23","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une lithiase biliaire compliquée : angiocholite aiguë","contenu":"<div class=\"notion-course\"><p>L’<strong><span><span class=\"nc-red nc-bold\">angiocholite</span></span><span class=\"nc-red nc-bold\"> aiguë</span></strong> est une <span><span class=\"nc-purple_bg\">infection aiguë</span> de la <span class=\"nc-red nc-bold\">voie biliaire principale</span></span> (germes digestifs : <span><span class=\"nc-purple nc-bold\">BGN</span></span>, plus rarement <span class=\"nc-purple nc-bold\">coques Gram +</span>), le plus souvent par enclavement <span class=\"nc-yellow_bg\">d’un calcul</span>.</p>\n      <div class=\"callout callout-danger\"><strong><span>Triade de Charcot</span>.</strong> Apparition successive en <span><span class=\"nc-red nc-bold\">48 h</span></span> (ordre chronologique, parfois incomplète) : 1. <span><span class=\"nc-blue_bg\">douleur biliaire</span></span> → 2. <span><span class=\"nc-blue_bg nc-bold\">fièvre</span>/frissons</span> (souvent au 1ᵉʳ plan, peut être <span class=\"nc-red_bg\">sévère</span> : <span><span class=\"nc-red nc-bold\">bactériémie</span></span>, <span><span class=\"nc-red nc-bold\">choc</span></span>) → 3. <span><span class=\"nc-yellow_bg\">ictère</span></span> (<span class=\"nc-yellow_bg\">survient après la douleur</span> ; son absence n’écarte pas le diagnostic).</div>\n      <table>\n        <thead><tr><th>Axe</th><th>Éléments</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Étiologies</strong></td><td>Enclavement d’un calcul dans la VBP ; sténose de la VBP (tumeur, <span>adénopathies</span>, <span>pancréatite chronique</span>) ; parasites migrants (distomatose, <span class=\"nc-purple nc-bold\">ascaridiose</span>)</td></tr>\n          <tr><td><strong>Biologie</strong></td><td><span><span class=\"nc-blue_bg\">Syndrome inflammatoire</span>/infectieux</span> ; <span><span class=\"nc-yellow_bg\">cholestase ictérique</span></span> (<span>bilirubine</span> à prédominance conjuguée) ; <span><span class=\"nc-blue_bg\">cytolyse hépatique</span></span> fréquente en phase aiguë</td></tr>\n          <tr><td><strong><span><span class=\"nc-brown_bg\">Échographie</span></span></strong></td><td><span><span class=\"nc-blue_bg\">Lithiase vésiculaire</span></span> ; paroi épaisse ; <span>dilatation de la VBP</span> (<span>inconstante</span>) ; calcul de la VBP (Se <span>30-50 %</span>)</td></tr>\n          <tr><td><strong>Microbiologie</strong></td><td><span>Hémocultures systématiques</span> (souvent positives à germes digestifs)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 281 — <span>Pancréatite chronique</span></em></p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>La triade douleur–<span class=\"nc-blue_bg nc-bold\">fièvre</span>–<span class=\"nc-yellow_bg\">ictère</span> est évocatrice mais inconstante ; son ordre et un délai de 48 heures ne sont pas requis. Une <span class=\"nc-pink nc-bold\">angiocholite</span> grave peut se présenter d’emblée par sepsis ou <span class=\"nc-red nc-bold\">choc</span>.</li></ul></div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":3},{"id":"277-24","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître l’examen paraclinique de première intention (en urgence) devant une angiocholite","contenu":"<div class=\"notion-course\"><div class=\"callout callout-info\"><strong><span class=\"nc-red nc-bold\">1ʳᵉ intention</span>.</strong> <span class=\"nc-blue nc-bold\">L’</span><strong><span><span class=\"nc-blue nc-bold\">échographie abdominale</span></span></strong> est l’examen de <span><span class=\"nc-red nc-bold\">première intention</span></span>, en <span><span class=\"nc-red nc-bold\">urgence</span></span>, devant une <span><span class=\"nc-red nc-bold\">angiocholite</span></span> (recherche de <span class=\"nc-blue nc-bold\">lithiase</span>, <span>dilatation de la VBP</span> — inconstante).</div>\n      <p>Examens de seconde intention pour la VBP : <span><span class=\"nc-blue_bg\">scanner</span></span> (signes indirects), <span><span class=\"nc-blue_bg\">cholangio</span>-<span class=\"nc-blue_bg\">IRM</span></span> et <span><span class=\"nc-blue nc-bold\">écho-endoscopie</span></span> (Se &gt; <span>90 %</span> pour la <span><span class=\"nc-blue nc-bold\">lithiase</span> de la VBP</span>).</p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":0},{"id":"277-25","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les trois évolutions possibles de l’angiocholite","contenu":"<div class=\"notion-course\"><p>Trois évolutions/complications graves de <span class=\"nc-red nc-bold\">l’</span><span><span class=\"nc-red nc-bold\">angiocholite</span></span> :</p>\n      <ul>\n        <li><span><span class=\"nc-red_bg\">Abcès hépatique</span></span></li>\n        <li><span><span class=\"nc-red_bg\">Choc septique</span></span><span class=\"nc-red_bg\"> / </span><span><span class=\"nc-red_bg\">défaillance multiviscérale</span></span></li>\n        <li><span>Angiocholite ictéro-urémigène</span> (associée à une <span><span class=\"nc-orange nc-bold\">insuffisance rénale</span></span>)</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span>Sepsis</span> et <span>choc <span class=\"nc-red nc-bold\">septique</span></span></em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":0},{"id":"277-26","rang":"A","rubrique":"Prise en charge","titre":"Connaître le traitement en cas de sepsis sévère ou choc septique lors d’une angiocholite","contenu":"<div class=\"notion-course\"><ul><li>Angiocholite : antibiothérapie IV, hémocultures si possible sans retard, réanimation et contrôle de l’obstacle biliaire. Ces mesures sont engagées en parallèle.</li><li>Drainage biliaire habituellement endoscopique par CPRE ; l’urgence est accrue en cas de choc ou de défaillance d’organe. Ne pas attendre la fin d’une réanimation prolongée ou tous les examens pour organiser le drainage.</li><li>Après contrôle de l’infection, traiter la cause, extraire les calculs selon situation et discuter la <span class=\"nc-pink nc-bold\">cholécystectomie</span>. Adapter antibiotiques aux résultats et à l’évolution.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":0},{"id":"277-27","rang":"B","rubrique":"Prise en charge","titre":"Connaître les deux principes du traitement de l’angiocholite aiguë et les modalités de la cholangiopancréatographie rétrograde endoscopique (CPRE)","contenu":"<div class=\"notion-course\"><p><strong>Deux principes :</strong></p>\n      <ul>\n        <li><strong><span>Antibiothérapie</span> :</strong> <span><span class=\"nc-pink_bg\">amoxicilline-acide clavulanique</span></span> ou <span><span class=\"nc-pink_bg\">C3G + imidazolé</span></span> pendant <span><span class=\"nc-pink nc-bold\">7 jours</span></span> (+ traitement symptomatique)</li>\n        <li><strong>Désobstruction de la VBP en <span><span class=\"nc-red nc-bold\">urgence</span></span> (<span><span class=\"nc-pink nc-bold\">&lt; 24 h</span></span>) :</strong> <span>CPRE</span> en 1ʳᵉ intention ; <span>drainage transcutané</span> si <span>CPRE</span> non disponible ou <span class=\"nc-red nc-bold\">patient instable</span></li>\n      </ul>\n      <p><strong>Modalités de la <span>CPRE</span></strong> (geste endoscopique sous AG) :</p>\n      <table>\n        <thead><tr><th>Item</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Déroulement</strong></td><td>Abord de la VBP ; <span><span class=\"nc-pink_bg\">sphinctérotomie endoscopique</span></span><span class=\"nc-pink_bg\"> du sphincter d’Oddi</span> ; <span class=\"nc-pink_bg\">extraction instrumentale du calcul</span></td></tr>\n          <tr><td><strong>Complications</strong> (<span>5-10 %</span>)</td><td><span><span class=\"nc-red_bg\">Pancréatite aiguë</span></span> (<span>5 %</span>, liée au PDC) ; <span><span class=\"nc-red nc-bold\">hémorragie</span></span> (<span>1 %</span>) ; <span><span class=\"nc-red nc-bold\">infection</span></span> ; <span><span class=\"nc-red nc-bold\">perforation</span> <span class=\"nc-red nc-bold\">duodénale</span></span> (<span>0,1-0,6 %</span>)</td></tr>\n          <tr><td><strong>Inconvénients</strong></td><td>Examen coûteux, invasif ; n’est plus réalisée à visée purement diagnostique</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong><span class=\"nc-pink nc-bold\">Cholécystectomie</span> (après désobstruction).</strong> <span><span class=\"nc-green_bg\">Angiocholite</span></span><span class=\"nc-green_bg\"> non sévère</span> → durant la <span><span class=\"nc-pink nc-bold\">même hospitalisation</span></span> ; <span class=\"nc-red_bg\">angiocholite sévère</span> → <span class=\"nc-pink nc-bold\">à distance</span>, <span><span class=\"nc-pink nc-bold\">&gt; 1 mois</span></span> ; <span class=\"nc-pink nc-bold\">parfois </span><span><span class=\"nc-pink nc-bold\">non réalisée</span></span> selon le <span>terrain</span> du malade (comorbidités, âge physiologique).</div><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>La CPRE est principalement thérapeutique. Elle expose notamment à pancréatite, <span class=\"nc-red nc-bold\">hémorragie</span>, <span class=\"nc-red nc-bold\">infection</span> et <span class=\"nc-red nc-bold\">perforation</span> ; prévention de la pancréatite par AINS rectal en l’absence de contre-indication et mesures techniques selon le risque.</li></ul></div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":2},{"id":"277-28","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens paracliniques pouvant être réalisés à la recherche d’un calcul de la voie biliaire principale (VBP)","contenu":"<div class=\"notion-course\"><table>\n        <thead><tr><th>Examen</th><th>Performance</th></tr></thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-brown_bg\">Échographie</span></span></td><td>1ʳᵉ intention mais <span>peu sensible</span> pour le calcul cholédocien (<span>Se 30-50 %</span>) ; montre la <span>dilatation de la VBP</span></td></tr>\n          <tr><td><span>Bili-IRM (<span class=\"nc-blue_bg\">cholangio-IRM</span>)</span></td><td>Très sensible (<span>Se &gt; 90 %</span>)</td></tr>\n          <tr><td><span><span class=\"nc-blue nc-bold\">Écho-endoscopie</span></span></td><td>Très sensible (<span>Se &gt; 90 %</span>)</td></tr>\n          <tr><td><span><span class=\"nc-blue_bg\">Cholangiographie per-opératoire</span></span></td><td>Examen sensible ; réalisée pendant la <span class=\"nc-pink nc-bold\">cholécystectomie</span></td></tr>\n          <tr><td><span><span class=\"nc-blue_bg nc-bold\">TDM</span></span></td><td>Valeur diagnostique <span>inférieure</span> à la <span class=\"nc-blue nc-bold\">bili-</span><span><span class=\"nc-blue nc-bold\">IRM</span></span> et à l’<span><span class=\"nc-blue nc-bold\">écho-endoscopie</span></span></td></tr>\n        </tbody>\n      </table></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":0},{"id":"277-29","rang":"B","rubrique":"Prise en charge","titre":"Connaître les deux traitements possibles pour désobstruer la VBP en dehors de l’urgence septique","contenu":"<div class=\"notion-course\"><p><span>Lithiase de la VBP</span> <span>sans angiocholite ni pancréatite</span> — deux options de désobstruction :</p>\n      <ul>\n        <li><strong><span class=\"nc-pink_bg\">Désobstruction chirurgicale en 1 temps</span> :</strong> <span><span class=\"nc-pink_bg\">cholécystectomie</span></span><span class=\"nc-pink_bg\"> avec </span><span><span class=\"nc-pink_bg\">désobstruction peropératoire de la VBP</span></span></li>\n        <li><strong>Désobstruction endoscopique en 2 temps :</strong> <span><span class=\"nc-pink_bg\">sphinctérotomie endoscopique</span></span><span class=\"nc-pink_bg\"> biliaire</span>, puis <span><span class=\"nc-pink_bg\">cholécystectomie</span></span></li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 278 — <span>Ictère</span></em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong><span class=\"kw-clinique\">Angiocholite</span> aiguë</strong></p><p><span class=\"kw-ttt\">CPRE</span> de désobstruction de la <span class=\"kw-def\">VBP</span> en <span class=\"kw-chiffre\">&lt; 24 h</span>. Si <span class=\"kw-alerte\">sepsis sévère</span>/<span class=\"kw-alerte\">choc</span>, <span class=\"kw-alerte\">réanimation AVANT</span> la <span class=\"kw-ttt\">CPRE</span></p><ul><li><span class=\"kw-alerte\">urgence vitale</span></li></ul><p><strong><span class=\"kw-clinique\">Cholécystite</span> aiguë</strong></p><p><span class=\"kw-ttt\">cholécystectomie</span> en <span class=\"kw-alerte\">urgence</span> par <span class=\"kw-ttt\">cœlioscopie</span> en <span class=\"kw-chiffre\">&lt; 72 h</span></p><p><strong><span class=\"kw-clinique\">Pancréatite aiguë</span> biliaire</strong></p><ul><li>hospit + <span class=\"kw-ttt\">cholécystectomie</span> même <span class=\"kw-alerte\">hospitalisation</span> si <em><span class=\"kw-def\">PA minime</span></em></li><li>retardée à <span class=\"kw-chiffre\">3-6 semaines</span> si <em><span class=\"kw-alerte\">PA sévère/nécrosante</span></em></li></ul><p><strong><span class=\"kw-clinique\">Colique hépatique</span> / migration</strong></p><ul><li><span class=\"kw-ttt\">antalgie</span> en <span class=\"kw-alerte\">urgence</span> par voie parentérale</li><li><span class=\"kw-ttt\">cholécystectomie</span> programmée <span class=\"kw-chiffre\">&lt; 1 mois</span> après la crise</li></ul>","hospit":"<p><strong>Ambulatoire :</strong> <span class=\"kw-def\">colique hépatique simple</span> une fois la crise calmée (programmation chir <span class=\"kw-chiffre\">&lt; 1 mois</span>) ; <span class=\"kw-def\">migration lithiasique</span> non compliquée.</p><p><strong><span class=\"kw-alerte\">Hospitalisation</span> conventionnelle :</strong> <span class=\"kw-def\">cholécystite aiguë</span> ; <span class=\"kw-def\">angiocholite non sévère</span> ; <span class=\"kw-def\">pancréatite aiguë biliaire</span> (selon <span class=\"kw-def\">Balthazar</span>).</p><p><strong><span class=\"kw-alerte\">Réanimation</span> :</strong> <span class=\"kw-def\">angiocholite</span> avec <span class=\"kw-alerte\">sepsis sévère</span> / <span class=\"kw-alerte\">choc septique</span> ; <span class=\"kw-alerte\">pancréatite aiguë sévère/nécrosante</span> ; <span class=\"kw-alerte\">défaillance multiviscérale</span>.</p><p><strong>Bloc en <span class=\"kw-alerte\">urgence</span> :</strong> <span class=\"kw-def\">cholécystite</span> (<span class=\"kw-chiffre\">&lt; 72 h</span>) ; <span class=\"kw-alerte\">péritonite biliaire</span> (<span class=\"kw-alerte\">perforation</span>) ; <span class=\"kw-alerte\">iléus biliaire</span> (<span class=\"kw-ttt\">incision-extraction</span>).</p><p><strong>Endoscopie interventionnelle :</strong> <span class=\"kw-ttt\">CPRE</span> pour <span class=\"kw-def\">angiocholite</span> (<span class=\"kw-chiffre\">&lt; 24 h</span>) ou <span class=\"kw-def\">lithiase de la VBP</span> (à distance hors urgence septique).</p>","redflags":"<ul><li><strong><span class=\"kw-clinique\">Triade de Charcot</span> :</strong> <span class=\"kw-clinique\">douleur biliaire</span> → <span class=\"kw-clinique\">fièvre</span>/<span class=\"kw-clinique\">frissons</span> → <span class=\"kw-clinique\">ictère</span> (apparition en <span class=\"kw-chiffre\">&lt; 48 h</span> ; signe une <span class=\"kw-def\">angiocholite</span>)</li><li><strong><span class=\"kw-clinique\">Sepsis</span> sévère / <span class=\"kw-alerte\">choc septique</span> :</strong> <span class=\"kw-alerte\">hypoTA</span>, <span class=\"kw-alerte\">marbrures</span>, <span class=\"kw-alerte\">oligurie</span>, <span class=\"kw-bio\">lactates</span> ↑ — réa avant <span class=\"kw-ttt\">CPRE</span></li><li><strong><span class=\"kw-clinique\">Angiocholite</span> ictéro-urémigène :</strong> <span class=\"kw-alerte\">insuffisance rénale</span> associée (3ᵉ <span class=\"kw-clinique\">évolution</span> possible de l'<span class=\"kw-def\">angiocholite</span>)</li><li><strong>Défense / contracture abdominale :</strong> <span class=\"kw-alerte\">cholécystite grave</span>, <span class=\"kw-alerte\">perforation</span>, <span class=\"kw-alerte\">péritonite biliaire</span></li><li><strong>Douleur biliaire persistante &gt;<span class=\"kw-chiffre\"> 6-24 h</span> :</strong> élimine la <span class=\"kw-def\">colique simple</span>, oriente vers une complication (<span class=\"kw-def\">cholécystite a minima</span>)</li><li><strong><span class=\"kw-clinique\">Ictère</span> + <span class=\"kw-clinique\">fièvre</span> :</strong> évoque l'<span class=\"kw-def\">angiocholite</span> jusqu'à preuve du contraire (ne JAMAIS attendre la <span class=\"kw-def\">triade complète</span>)</li><li><strong><span class=\"kw-bio\">Lipase</span> <span class=\"kw-chiffre\">≥ 3</span> N + douleur transfixiante permanente :</strong> <span class=\"kw-def\">pancréatite aiguë biliaire</span> (vérifier <span class=\"kw-def\">Balthazar</span> / <span class=\"kw-def\">score de Ranson</span> / <span class=\"kw-def\">BISAP</span>)</li><li><strong>Aérobilie sur <span class=\"kw-imagerie\">TDM</span></strong> + <span class=\"kw-clinique\">syndrome occlusif</span> chez le <span class=\"kw-etio\">sujet âgé</span> : <span class=\"kw-def\">iléus biliaire</span> (<span class=\"kw-def\">fistule bilio-digestive</span>)</li><li><strong><span class=\"kw-bio\">Hémocultures</span> positives à BGN :</strong> <span class=\"kw-etio\">origine biliaire</span> à rechercher systématiquement</li></ul>","principes":"<p>Repères de conduite à tenir, reliés aux objectifs détaillés :</p><ul><li><strong>Connaître les caractéristiques de la douleur biliaire</strong> — La colique hépatique est la traduction douloureuse du blocage transitoire d’un calcul.</li><li><strong>Connaître les trois principaux diagnostics différentiels à évoquer devant une colique hépatique</strong> — Devant une douleur épigastrique / de l’hypochondre droit, trois diagnostics différentiels principaux à éliminer :\n      \n        SCA (syndrome coronarien aigu) — surtout en cas de douleur épigastrique trompeuse\n        UGD (ulcère gastro-duodénal)\n        Pancréatite aiguë\n      \n      📎 Items liés : 339 — Syndrome coronarien aiguë · 272 — Ulcère gastroduodénal - gastrite · 358 — Pancréatite aiguë.</li><li><strong>Connaître les éléments du diagnostic positif de la lithiase vésiculaire symptomatique simple</strong> — Le diagnostic de lithiase vésiculaire symptomatique simple repose sur un faisceau clinico-biologique-échographique :\n      \n        AxeÉléments\n        \n          CliniqueColique hépatique &lt; 6 h ; pas de fièvre ; pas d’ictère ; signe de Murphy\n          BiologieAucune anomalie : bilan hépatique normal ; pas de syndrome inflammatoire (sauf si migration lithiasique associée)\n          ÉchographieCalculs vésiculaires : hyperéchogènes ; cône d’ombre postérieur ; mobiles avec le patient (Se 95 %, meilleure que TDM/IRM).</li><li><strong>Connaître les principes du traitement de la pathologie lithiasique symptomatique</strong> — Deux volets : soulager la crise, puis prévenir la récidive.\n      \n        Traitement de la crise (en urgence, voie parentérale) :\n          antispasmodiques (phloroglucinol ou trimébutine) ; antalgiques ± AINS en l’absence de contre-indication\n        Cholécystectomie (sous cœlioscopie de préférence) pour éviter récidive/complication, réalisée rapidement une fois la crise calmée (&lt; 1 mois)\n      .</li><li><strong>Connaître le mécanisme et savoir diagnostiquer une migration lithiasique</strong> — Mécanisme : migration de petits calculs dans la voie biliaire principale, le plus souvent transitoire (le calcul passe puis est évacué).\n      Diagnostic :\n      \n        Élévation transitoire des transaminases, diminuant de &gt; 50 % en &lt; 48 h (bilirubine et γ-GT normales)\n        Échographie : parois vésiculaires fines, dilatation modérée ± inconstante de la VBP, calcul rarement vu dans la VBP (écho souvent identique à une colique hépatique simple)\n      \n      Discriminant.</li></ul>","suivi":"<p><strong>Post-<span class=\"kw-imagerie\">CPRE</span> :</strong> <span class=\"kw-def\">surveillance</span> des complications (<span class=\"kw-chiffre\">5-10 %</span>) — <span class=\"kw-alerte\">pancréatite aiguë</span> (<span class=\"kw-chiffre\">5 %</span>, liée au <span class=\"kw-imagerie\">PDC</span>), <span class=\"kw-alerte\">hémorragie</span> (<span class=\"kw-chiffre\">1 %</span>), <span class=\"kw-alerte\">infection</span>, <span class=\"kw-alerte\">perforation duodénale</span> (<span class=\"kw-chiffre\">0,1-0,6 %</span>).</p><p><strong>Post-cholécystectomie :</strong> reprise précoce de l'alimentation ; surveillance de la cicatrisation ; pas de <span class=\"kw-def\">prévention secondaire</span> spécifique (récidive rare).</p><p><strong>Cholécystectomie systématique post-cure</strong> de toute <span class=\"kw-def\">lithiase symptomatique/compliquée</span> pour éviter la récidive (sauf <span class=\"kw-def\">terrain</span> contre-indiquant la chir : <span class=\"kw-etio\">comorbidités</span>, <span class=\"kw-etio\">âge physiologique</span>).</p><p><strong>Lithiase VBP résiduelle :</strong> à dépister si tableau persistant — <span class=\"kw-imagerie\">bili-IRM</span> ou <span class=\"kw-imagerie\">écho-endoscopie</span> (<span class=\"kw-chiffre\">Se &gt; 90 %</span>).</p><p><strong>Reconsultation</strong> immédiate si récidive de <span class=\"kw-clinique\">douleur biliaire</span>, <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">ictère</span> ou <span class=\"kw-clinique\">syndrome occlusif</span> (<span class=\"kw-def\">iléus biliaire</span> à distance).</p>"},"liensGlobaux":[{"href":"https://moodle.umontpellier.fr/pluginfile.php/1394203/mod_folder/content/0/voie%20biliaires%20-%20r%C3%A9um%C3%A9.pdf","label":"Voie biliaires   réumé"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Suspicion de lithiase biliaire symptomatique — Douleur biliaire (épigastre/HCD, brutale, irradiation omoplate) ± fièvre ± ictère","detail":"<h4>CAT — Lithiase biliaire symptomatique — Discrimination des 5 entités cliniques et orientation thérapeutique</h4>","branches":[{"to":"q-migr","label":"Douleur < 6 h","color":"green"},{"to":"q-fievre","label":"Douleur > 6 h","color":"amber"}]},{"id":"q-migr","kind":"decision","label":"Élévation transitoire des transaminases (↓ <span class=\"kw-chiffre\">> 50 %</span> en <span class=\"kw-chiffre\">< 48</span> h) ? — Cinétique = meilleur signe ; écho souvent identique à une colique simple","branches":[{"to":"t-migration","label":"Oui (pic transaminases ; γ-GT/bili N)","color":"amber"},{"to":"t-colique","label":"Non (bilan normal)","color":"green"}]},{"id":"t-migration","kind":"terminal","label":"Migration lithiasique","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-def\">Colique hépatique</span> < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">6 h</span></span> ; pas de <span class=\"kw-clinique\">fièvre</span> ; pas d'<span class=\"kw-clinique\">ictère</span></li></ul><h4>Biologie</h4><ul><li>Élévation transitoire des <span class=\"kw-bio\">transaminases</span> (↓ > <span class=\"kw-chiffre\">50 %</span> en < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">48 h</span></span>) ; <span class=\"kw-bio\">bilirubine</span> et <span class=\"kw-bio\">γ-GT</span> normales</li></ul><h4>Imagerie</h4><ul><li>1ʳᵉ intention = <span class=\"kw-imagerie\">échographie abdominale</span> (<span class=\"kw-chiffre\">Se médiocre</span> pour le calcul cholédocien) ; <span class=\"kw-imagerie\">bili-IRM</span> / <span class=\"kw-imagerie\">écho-endoscopie</span> en 2ᵉ intention si doute</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Antalgie parentérale</span> (<span class=\"kw-ttt\">phloroglucinol</span>/<span class=\"kw-ttt\">trimébutine</span> + <span class=\"kw-ttt\">antalgiques</span> ± <span class=\"kw-ttt\">AINS</span>)</li><li><span class=\"kw-ci\">Pas d'antibiothérapie</span></li><li><span class=\"kw-ttt\">Cholécystectomie cœlioscopique</span> programmée < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">1 mois</span></span> après la crise</li></ul><h4>Délai</h4><ul><li>Crise calmée → ambu ; <span class=\"kw-ttt\">chirurgie</span> programmée < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">1 mois</span></span></li></ul>"},{"id":"t-colique","kind":"terminal","label":"Colique hépatique simple","color":"green","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Douleur biliaire</span> brutale < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">6 h</span></span> ; <span class=\"kw-clinique\">signe de Murphy</span> ; PAS de <span class=\"kw-clinique\">fièvre</span>, PAS d'<span class=\"kw-clinique\">ictère</span></li></ul><h4>Biologie</h4><ul><li>Aucune anomalie (<span class=\"kw-bio\">bilan hépatique</span> normal, pas de <span class=\"kw-bio\">syndrome inflammatoire</span>)</li></ul><h4>Imagerie</h4><ul><li><span class=\"kw-imagerie\">Échographie abdominale</span> (<span class=\"kw-chiffre\">Se 95 %</span> pour calculs vésiculaires) — <span class=\"kw-imagerie\">calculs hyperéchogènes</span>, <span class=\"kw-imagerie\">cône d'ombre</span>, <span class=\"kw-imagerie\">mobiles</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Antalgie parentérale</span> en <span class=\"kw-alerte\">urgence</span> (<span class=\"kw-ttt\">phloroglucinol</span>/<span class=\"kw-ttt\">trimébutine</span> + <span class=\"kw-ttt\">antalgiques</span> ± <span class=\"kw-ttt\">AINS</span> hors CI)</li><li><span class=\"kw-ttt\">Cholécystectomie cœlioscopique</span> programmée < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">1 mois</span></span> après la crise (prévention récidive/complication)</li></ul><h4>Diagnostics différentiels</h4><ul><li><span class=\"kw-def\">SCA</span> · <span class=\"kw-def\">UGD</span> · <span class=\"kw-def\">pancréatite aiguë</span></li></ul>"},{"id":"q-fievre","kind":"decision","label":"Fièvre / syndrome infectieux ? — Fièvre = élimine la colique simple, oriente vers infection biliaire","branches":[{"to":"q-pa","label":"Non (apyrétique)","color":"amber"},{"to":"q-ictere","label":"Oui (fièvre + frissons)","color":"red"}]},{"id":"q-pa","kind":"decision","label":"Douleur transfixiante permanente + lipase ≥ 3 N ? — Critères biologiques de pancréatite aiguë","branches":[{"to":"t-pa","label":"Oui (lipase ≥ 3 N)","color":"amber"},{"to":"t-atypique","label":"Non (lipase normale)","color":"blue"}]},{"id":"t-pa","kind":"terminal","label":"Pancréatite aiguë biliaire","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Douleur transfixiante et permanente</span> ; <span class=\"kw-clinique\">fièvre</span> ± ; pas d'<span class=\"kw-clinique\">ictère</span></li></ul><h4>Biologie</h4><ul><li><span class=\"kw-bio\">Lipase ≥ 3 N</span> ; pic précoce et transitoire des <span class=\"kw-bio\">transaminases</span> (< <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">48 h</span></span>, <span class=\"kw-bio\">ASAT</span> prédomine d'abord puis <span class=\"kw-bio\">ALAT</span>) ; <span class=\"kw-bio\">bilirubine totale</span> > <span class=\"kw-chiffre\">40 µmol/L</span> = <span class=\"kw-def\">blocage ampullaire</span></li></ul><h4>Imagerie</h4><ul><li><span class=\"kw-imagerie\">Échographie abdominale</span> en <span class=\"kw-alerte\">urgence</span> (< <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">48 h</span></span>) ; <span class=\"kw-imagerie\">bili-IRM</span> / <span class=\"kw-imagerie\">écho-endoscopie</span> si doute. Arguments d'origine biliaire : <span class=\"kw-imagerie\">calculs vésiculaires</span> petits (< <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">3 mm</span></span>) et nombreux (<span class=\"kw-chiffre\">≥ 4</span>), <span class=\"kw-imagerie\">canal cystique large</span>, <span class=\"kw-imagerie\">dilatation VBP</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-alerte\">Hospitalisation</span> + <span class=\"kw-ttt\">antalgie</span></li><li><span class=\"kw-ci\">Pas d'antibiothérapie systématique</span></li><li><span class=\"kw-ttt\">CPRE</span> seulement si suspicion d'<span class=\"kw-def\">angiocholite</span> associée (<span class=\"kw-alerte\">urgence</span> < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">24 h</span></span>) ou de <span class=\"kw-def\">calcul VBP résiduel</span> (à distance)</li><li><span class=\"kw-ttt\">Cholécystectomie</span> systématique : même <span class=\"kw-alerte\">hospitalisation</span> si <span class=\"kw-def\">PA minime</span> ; à <span class=\"kw-chiffre\">3-6 semaines</span> si <span class=\"kw-alerte\">PA sévère/nécrosante</span></li></ul><h4>Renvoi</h4><ul><li>Item 358 — <span class=\"kw-clinique\">Pancréatite aiguë</span></li></ul>"},{"id":"t-atypique","kind":"terminal","label":"Douleur biliaire prolongée atypique — réévaluer","color":"blue","detail":"<h4>Conduite</h4><ul><li>Pas de tableau franc des 5 entités lithiasiques ; reprendre interrogatoire, refaire bilan à <span class=\"kw-chiffre\">H+6</span> (<span class=\"kw-bio\">transaminases</span>, <span class=\"kw-bio\">lipase</span>, <span class=\"kw-bio\">CRP</span>), refaire <span class=\"kw-imagerie\">échographie</span></li></ul><h4>Diagnostics différentiels à éliminer</h4><ul><li><span class=\"kw-def\">SCA</span> (<span class=\"kw-clinique\">épigastralgie</span> trompeuse)</li><li><span class=\"kw-def\">UGD compliqué</span></li><li><span class=\"kw-def\">Cholécystite a minima</span> (<span class=\"kw-imagerie\">paroi > 4 mm</span> ?)</li><li>Autre cause d'<span class=\"kw-clinique\">abdomen aigu</span></li></ul><h4>Renvois</h4><ul><li>Item 269 — Douleur abdominale aiguë · Item 339 — <span class=\"kw-alerte\">SCA</span> · Item 272 — <span class=\"kw-clinique\">UGD</span></li></ul>"},{"id":"q-ictere","kind":"decision","label":"Ictère ± dilatation VBP à l'échographie ? — Triade de Charcot = douleur + fièvre + ictère (en 48 h, parfois incomplète)","branches":[{"to":"t-angio","label":"Oui (triade ± complète, dilatation VBP)","color":"red"},{"to":"t-cholecy","label":"Non (pas d'ictère, pas de dilatation VBP)","color":"amber"}]},{"id":"t-angio","kind":"terminal","label":"Angiocholite aiguë","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-def\">Triade de Charcot</span> : <span class=\"kw-clinique\">douleur biliaire</span> → <span class=\"kw-clinique\">fièvre</span>/<span class=\"kw-clinique\">frissons</span> → <span class=\"kw-clinique\">ictère</span> (apparition en < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">48 h</span></span>, ordre chronologique ; absence d'<span class=\"kw-clinique\">ictère</span> n'écarte PAS le diagnostic)</li></ul><h4>Biologie</h4><ul><li><span class=\"kw-bio\">Syndrome inflammatoire/infectieux</span> ; <span class=\"kw-bio\">cholestase ictérique</span> (<span class=\"kw-bio\">bilirubine conjuguée</span>) ; <span class=\"kw-bio\">cytolyse hépatique</span> ; <span class=\"kw-bio\">hémocultures</span> systématiques (<span class=\"kw-etio\">BGN</span> d'origine digestive)</li></ul><h4>Imagerie</h4><ul><li>1ʳᵉ intention = <span class=\"kw-imagerie\">échographie</span> en <span class=\"kw-alerte\">urgence</span> (<span class=\"kw-imagerie\">lithiase vésiculaire</span>, <span class=\"kw-imagerie\">paroi épaisse</span>, <span class=\"kw-imagerie\">dilatation VBP</span> inconstante, <span class=\"kw-imagerie\">calcul VBP</span> <span class=\"kw-chiffre\">Se 30-50 %</span>) ; 2ᵉ intention <span class=\"kw-imagerie\">bili-IRM</span> / <span class=\"kw-imagerie\">écho-endoscopie</span> (<span class=\"kw-chiffre\">Se > 90 %</span>)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Antibiothérapie</span> : <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span> OU <span class=\"kw-ttt\">C3G + imidazolé</span> × <span class=\"kw-chiffre\">7 j</span></li><li><span class=\"kw-ttt\">CPRE</span> avec <span class=\"kw-ttt\">sphinctérotomie endoscopique</span> < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">24 h</span></span> (1ʳᵉ intention)</li><li><span class=\"kw-ttt\">Drainage transcutané</span> sous guidage écho si <span class=\"kw-ttt\">CPRE</span> non disponible OU patient instable</li><li>⚠️ Si <span class=\"kw-alerte\">sepsis sévère</span> / <span class=\"kw-alerte\">choc septique</span> : <span class=\"kw-alerte\">RÉANIMATION</span> (<span class=\"kw-ttt\">remplissage</span>, <span class=\"kw-ttt\">vasopresseurs</span>, <span class=\"kw-bio\">hémocultures</span>) AVANT la <span class=\"kw-ttt\">CPRE</span></li><li><span class=\"kw-ttt\">Cholécystectomie</span> après <span class=\"kw-ttt\">CPRE</span> : même <span class=\"kw-alerte\">hospitalisation</span> si non sévère ; > <span class=\"kw-chiffre\">1 mois</span> si sévère ; parfois non réalisée selon <span class=\"kw-def\">terrain</span></li></ul><h4>3 évolutions possibles</h4><ul><li><span class=\"kw-alerte\">Abcès hépatique</span></li><li><span class=\"kw-alerte\">Choc septique</span> / <span class=\"kw-alerte\">défaillance multiviscérale</span></li><li><span class=\"kw-alerte\">Angiocholite ictéro-urémigène</span> (<span class=\"kw-alerte\">insuffisance rénale</span>)</li></ul><h4>Renvois</h4><ul><li>Item 158 — <span class=\"kw-clinique\">Sepsis</span> · Item 278 — <span class=\"kw-clinique\">Ictère</span> · Item 281 — <span class=\"kw-clinique\">Pancréatite chronique</span> (sténose VBP)</li></ul>"},{"id":"t-cholecy","kind":"terminal","label":"Cholécystite aiguë","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Douleur</span> > <span class=\"kw-chiffre\">6 h</span> (souvent > <span class=\"kw-chiffre\">24 h</span>) ; <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">frissons</span> ; PAS d'<span class=\"kw-clinique\">ictère</span> (sauf <span class=\"kw-def\">syndrome de Mirizzi</span>) ; <span class=\"kw-alerte\">signes d'irritation péritonéale</span> possibles si forme grave</li></ul><h4>Biologie</h4><ul><li><span class=\"kw-bio\">Syndrome inflammatoire</span> (<span class=\"kw-bio\">PNN</span>, <span class=\"kw-bio\">CRP</span>/<span class=\"kw-bio\">PCT</span>) ; <span class=\"kw-bio\">bilan hépatique</span> normal ; <span class=\"kw-bio\">lipase</span> normale</li></ul><h4>Imagerie</h4><ul><li>1ʳᵉ intention = <span class=\"kw-imagerie\">échographie</span> : <span class=\"kw-imagerie\">paroi > 4 mm en triple feuillet</span>, <span class=\"kw-imagerie\">distension > 4 cm</span>, <span class=\"kw-imagerie\">calcul vésiculaire</span>, <span class=\"kw-imagerie\">Murphy échographique</span>. 2ʳᵉ intention = <span class=\"kw-imagerie\">scanner</span> si doute</li></ul><h4>Traitement</h4><ul><li>Symptomatique : <span class=\"kw-ttt\">remplissage</span> + <span class=\"kw-ttt\">phloroglucinol</span>/<span class=\"kw-ttt\">trimébutine</span> + <span class=\"kw-ttt\">antalgiques</span> + <span class=\"kw-ttt\">AINS</span></li><li><span class=\"kw-ttt\">Antibiothérapie</span> : <span class=\"kw-ttt\">Augmentin</span> OU <span class=\"kw-ttt\">C3G + imidazolé</span> × <span class=\"kw-chiffre\">7 j</span></li><li><span class=\"kw-ttt\">Cholécystectomie</span> en <span class=\"kw-alerte\">URGENCE</span> par <span class=\"kw-ttt\">cœlioscopie</span> < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">72 h</span></span></li></ul><h4>Complications septiques (ordre d'aggravation)</h4><ul><li><span class=\"kw-alerte\">Empyème vésiculaire</span></li><li><span class=\"kw-alerte\">Gangrène vésiculaire</span></li><li><span class=\"kw-alerte\">Perforation</span> → <span class=\"kw-alerte\">abcès péri-vésiculaire / hépatique</span></li><li><span class=\"kw-alerte\">Péritonite biliaire</span> (localisée puis généralisée)</li></ul><h4>Renvoi</h4><ul><li>Item 357 — <span class=\"kw-clinique\">Péritonite</span> aiguë</li></ul>"}]},"cards":[{"i":"2cd7b75add0d","n":277,"o":"277-1","u":"Définition","t":"Connaître la définition d’une lithiase biliaire et des différentes complications","q":"Qu'est-ce qu'une cholécystite aiguë et quel est son mécanisme ?","a":"<div class=\"notion-course\"><p>Cholécystite aiguë : inflammation de la vésicule, habituellement sur obstruction du <span class=\"nc-purple nc-bold\">canal cystique</span> ; l’<span class=\"nc-red nc-bold\">infection</span> peut être secondaire, elle n’est pas indispensable à la définition.</p></div>"},{"i":"366d9b6139d7","n":277,"o":"277-1","u":"Définition","t":"Connaître la définition d’une lithiase biliaire et des différentes complications","q":"Quelle est la définition d'une lithiase biliaire ?","a":"<div class=\"notion-course\"><p>La lithiase biliaire est définie par la présence de <strong>calculs</strong> formés à partir de la <strong>bile</strong>.</p></div>"},{"i":"4219f1427f47","n":277,"o":"277-1","u":"Définition","t":"Connaître la définition d’une lithiase biliaire et des différentes complications","q":"Qu'est-ce qu'une lithiase vésiculaire et quelle est sa fréquence symptomatique ?","a":"<div class=\"notion-course\"><p>La <span class=\"nc-blue_bg\">lithiase vésiculaire</span> correspond à la présence <span class=\"nc-yellow_bg\">d'un calcul</span> formé à partir de la bile, localisé dans la <strong>vésicule biliaire</strong>. Elle est la forme la plus fréquente de lithiase biliaire et est <span class=\"nc-orange nc-bold\">asymptomatique</span> dans <strong>80 %</strong> des cas.</p></div>"},{"i":"5d2ce9ee0d28","n":277,"o":"277-1","u":"Définition","t":"Connaître la définition d’une lithiase biliaire et des différentes complications","q":"Quelle est la définition et le mécanisme de l'angiocholite ?","a":"<div class=\"notion-course\"><p>L'angiocholite est une <strong>infection bactérienne</strong> de la voie biliaire principale (VBP), causée par <span class=\"nc-red nc-bold\">l'</span><strong><span class=\"nc-red nc-bold\">enclavement d'un calcul</span></strong><span class=\"nc-red nc-bold\"> au niveau de l'ampoule de Vater</span>.</p></div>"},{"i":"8e12f8a7ea4a","n":277,"o":"277-1","u":"Définition","t":"Connaître la définition d’une lithiase biliaire et des différentes complications","q":"Quel est l'impact d'une lithiase de la voie biliaire principale (VBP) ?","a":"<div class=\"notion-course\"><p>Une lithiase de la VBP correspond à la présence <span class=\"nc-yellow_bg\">d'un calcul</span> <span class=\"nc-red nc-bold\">dans la voie biliaire principale</span>. Si l'obstruction est prolongée, elle peut entraîner un <strong><span class=\"nc-orange nc-bold\">ictère</span></strong>.</p></div>"},{"i":"b48a4dc7a2a9","n":277,"o":"277-1","u":"Définition","t":"Connaître la définition d’une lithiase biliaire et des différentes complications","q":"Comment se définit la colique hépatique dans le contexte de la lithiase biliaire ?","a":"<div class=\"notion-course\"><p>Une <span class=\"nc-orange_bg\">colique hépatique</span> est une douleur causée <span class=\"nc-green_bg\">par</span> la <strong>mise en tension brutale des voies biliaires</strong>, secondaire au <span class=\"nc-yellow_bg\">blocage</span> <span class=\"nc-yellow_bg nc-bold\">transitoire</span> <span class=\"nc-yellow_bg\">d'un calcul</span> au niveau du <strong><span class=\"nc-purple nc-bold\">canal cystique</span></strong> ou de la <strong><span class=\"nc-purple nc-bold\">voie biliaire principale</span> (VBP)</strong>.</p></div>"},{"i":"bab87aafcdec","n":277,"o":"277-1","u":"Définition","t":"Connaître la définition d’une lithiase biliaire et des différentes complications","q":"Qu'est-ce que l'iléus biliaire ?","a":"<div class=\"notion-course\"><p>L'iléus biliaire est un <strong>syndrome occlusif</strong> causé par l'obstruction duodénale ou iléale par un <strong>calcul biliaire</strong>.</p></div>"},{"i":"c5eebda82491","n":277,"o":"277-1","u":"Définition","t":"Connaître la définition d’une lithiase biliaire et des différentes complications","q":"Quel est le mécanisme de la pancréatite aiguë lithiasique ?","a":"<div class=\"notion-course\"><p>La pancréatite aiguë lithiasique est une <strong><span class=\"nc-red nc-bold\">inflammation aiguë</span> du pancréas</strong>, secondaire à la <strong>migration d'un calcul</strong> dans l'ampoule de Vater.</p></div>"},{"i":"d6a23850b4b4","n":277,"o":"277-10","u":"Diagnostic positif","t":"Connaître les trois principaux diagnostics différentiels à évoquer devant une colique hépatique","q":"Quels sont les trois principaux diagnostics différentiels à évoquer devant une colique hépatique ?","a":"<div class=\"notion-course\"><p>Devant une douleur épigastrique ou de l'hypochondre droit pouvant évoquer une <span class=\"nc-orange_bg\">colique hépatique</span>, les trois <span class=\"nc-pink nc-bold\">diagnostics différentiels</span> principaux à éliminer sont :</p><ul><li>Le <strong>syndrome coronarien aigu (SCA)</strong>, surtout si la douleur épigastrique est trompeuse.</li><li>L'<strong>ulcère gastro-duodénal (UGD)</strong>.</li><li>La <strong>pancréatite aiguë</strong>.</li></ul></div>"},{"i":"66433f3cf08f","n":277,"o":"277-12","u":"Prise en charge","t":"Connaître les principes du traitement de la pathologie lithiasique symptomatique","q":"Quel est le traitement médical de la crise de lithiase biliaire (colique hépatique) ?","a":"<div class=\"notion-course\"><p>En <span class=\"nc-green_bg\">urgence</span>, <span class=\"nc-green_bg\">par</span> <span class=\"nc-green_bg\">voie</span> <span class=\"nc-green_bg\">parentérale</span>, il comprend :</p><ul><li>Des <strong>antispasmodiques</strong> (<span class=\"nc-green_bg\">par</span> exemple, <strong><span class=\"nc-pink nc-bold\">phloroglucinol</span></strong> ou <strong><span class=\"nc-pink nc-bold\">trimébutine</span></strong>).</li><li>Des <strong>antalgiques</strong>, associés à des <strong>AINS</strong> en l'absence de contre-indication.</li></ul></div>"},{"i":"a3aa55aa647b","n":277,"o":"277-12","u":"Prise en charge","t":"Connaître les principes du traitement de la pathologie lithiasique symptomatique","q":"Quels sont les deux grands volets de la prise en charge de la lithiase biliaire symptomatique ?","a":"<div class=\"notion-course\"><p>Les deux grands volets de la prise en charge sont :</p><ul><li>Soulager la <strong>crise</strong>.</li><li>Prévenir la <strong>récidive</strong>.</li></ul></div>"},{"i":"dc0f8f1e1f17","n":277,"o":"277-12","u":"Prise en charge","t":"Connaître les principes du traitement de la pathologie lithiasique symptomatique","q":"Quel est le traitement préventif de la récidive et des complications de la lithiase biliaire symptomatique ?","a":"<div class=\"notion-course\"><p>Le traitement préventif de choix est la <strong><span class=\"nc-pink nc-bold\">cholécystectomie</span></strong>. Idéalement réalisée sous <strong>cœlioscopie</strong>, elle est effectuée rapidement une fois la crise calmée, généralement dans le mois suivant (<strong><span class=\"nc-red nc-bold\">&lt; 1 mois</span></strong>).</p></div>"},{"i":"744979bdfa74","n":277,"o":"277-13","u":"Examens complémentaires","t":"Connaître l’indication des examens d’imagerie devant une lithiase biliaire","q":"Quelle est la performance diagnostique de l'échographie abdominale pour les calculs vésiculaires ?","a":"<div class=\"notion-course\"><p><span class=\"nc-blue nc-bold\">L'échographie abdominale</span> présente une <strong><span class=\"nc-pink nc-bold\">sensibilité</span> de 95 %</strong> pour la détection des calculs vésiculaires. Elle est considérée comme supérieure au <span class=\"nc-blue_bg\">scanner</span> (TDM) et à l'<span class=\"nc-blue_bg\">IRM</span> pour cette indication.</p></div>"},{"i":"810f2b700fac","n":277,"o":"277-13","u":"Examens complémentaires","t":"Connaître l’indication des examens d’imagerie devant une lithiase biliaire","q":"Dans quelles situations le scanner abdominal ou la bili-IRM sont-ils envisagés en seconde intention pour une lithiase biliaire ?","a":"<div class=\"notion-course\"><p>Le <span class=\"nc-blue_bg\">scanner abdominal</span> ou la <span class=\"nc-blue_bg\">bili-IRM</span> peuvent être discutés en seconde intention dans l'exploration d'une <span class=\"nc-blue nc-bold\">lithiase</span> biliaire, notamment pour confirmer certaines <span class=\"nc-red nc-bold\">complications</span> de la <span class=\"nc-blue nc-bold\">lithiase</span> biliaire. Ils n'ont <strong>pas d'indication</strong> en cas de <strong>calcul vésiculaire isolé</strong>.</p></div>"},{"i":"f8e24bbf4773","n":277,"o":"277-13","u":"Examens complémentaires","t":"Connaître l’indication des examens d’imagerie devant une lithiase biliaire","q":"Quel est l'examen d'imagerie de première intention pour l'exploration d'une lithiase biliaire symptomatique ?","a":"<div class=\"notion-course\"><p>L'examen de <span class=\"nc-red nc-bold\">première intention</span> pour explorer une <span class=\"nc-pink nc-bold\">lithiase biliaire symptomatique</span> est <span class=\"nc-blue nc-bold\">l'</span><strong><span class=\"nc-blue nc-bold\">échographie abdominale</span></strong>.</p></div>"},{"i":"42dfdd8a3af8","n":277,"o":"277-14","u":"Diagnostic positif","t":"Connaître le mécanisme et savoir diagnostiquer une migration lithiasique","q":"Quel est le mécanisme d'une migration lithiasique dans le contexte d'une lithiase biliaire ?","a":"<div class=\"notion-course\"><p>La migration lithiasique correspond au passage de <strong>petits calculs</strong> de la vésicule biliaire vers la <strong>voie biliaire principale (VBP)</strong>. Ce phénomène est le plus souvent <strong><span class=\"nc-yellow_bg nc-bold\">transitoire</span></strong>, les calculs étant ensuite évacués spontanément.</p></div>"},{"i":"6b3efa523c9a","n":277,"o":"277-14","u":"Diagnostic positif","t":"Connaître le mécanisme et savoir diagnostiquer une migration lithiasique","q":"Comment l'échographie hépato-biliaire se présente-t-elle le plus souvent lors d'une migration lithiasique ?","a":"<div class=\"notion-course\"><p>L'<span class=\"nc-blue nc-bold\">échographie</span> hépato-biliaire peut montrer :</p><ul><li>Des <strong>parois vésiculaires fines</strong>.</li><li>Une <strong>dilatation modérée et inconstante de la voie biliaire principale (VBP)</strong>.</li><li>Le <strong>calcul est rarement visualisé</strong> directement dans la VBP.</li></ul><p>Les images échographiques sont souvent similaires à celles d'une simple <span class=\"nc-orange_bg\">colique hépatique</span>, d'où l'importance de la cinétique des transaminases.</p></div>"},{"i":"b926fa72910f","n":277,"o":"277-14","u":"Diagnostic positif","t":"Connaître le mécanisme et savoir diagnostiquer une migration lithiasique","q":"Quel est le signe biologique le plus discriminant d'une migration lithiasique ?","a":"<div class=\"notion-course\"><p>Le signe biologique le plus discriminant est l'<strong><span class=\"nc-blue_bg\">élévation transitoire des transaminases</span></strong> (ASAT, ALAT). Leur particularité est de <strong>diminuer de plus de 50 % en moins de 48 heures</strong>. La bilirubine et les gamma-GT sont généralement normales ou n'ont pas encore eu le temps de s'élever.</p></div>"},{"i":"2c3e84680eee","n":277,"o":"277-15","u":"Examens complémentaires","t":"Connaître l’indication des examens d’imagerie devant une migration lithiasique","q":"Quel est l'examen d'imagerie de première intention à réaliser devant une suspicion de migration lithiasique dans le cadre d'un tableau de colique hépatique ?","a":"<div class=\"notion-course\"><p>L'examen de <span class=\"nc-red nc-bold\">première intention</span> est <span class=\"nc-blue nc-bold\">l'</span><strong><span class=\"nc-blue nc-bold\">échographie abdominale</span></strong>.</p></div>"},{"i":"b70598ed888f","n":277,"o":"277-15","u":"Examens complémentaires","t":"Connaître l’indication des examens d’imagerie devant une migration lithiasique","q":"Étant donné les limites de l'échographie, sur quel élément biologique repose majoritairement le diagnostic de migration lithiasique du cholédoque ?","a":"<div class=\"notion-course\"><p>Le diagnostic repose essentiellement sur l'<strong><span class=\"nc-blue_bg\">élévation transitoire des transaminases</span></strong>.</p></div>"},{"i":"bd681324a1ae","n":277,"o":"277-15","u":"Examens complémentaires","t":"Connaître l’indication des examens d’imagerie devant une migration lithiasique","q":"Quelles sont les limites de l'échographie abdominale dans le diagnostic d'une migration lithiasique dans le cholédoque ?","a":"<div class=\"notion-course\"><ul><li>Elle met rarement en évidence la <strong><span class=\"nc-yellow_bg\">dilatation de la voie biliaire principale</span> (VBP)</strong>.</li><li>Elle met rarement en évidence un <strong>calcul cholédocien</strong>.</li><li>Elle ne montre souvent que les <strong>calculs vésiculaires</strong> (dans la vésicule biliaire).</li></ul></div>"},{"i":"cc7df5a95cc0","n":277,"o":"277-15","u":"Examens complémentaires","t":"Connaître l’indication des examens d’imagerie devant une migration lithiasique","q":"Quels sont les examens d'imagerie les plus performants pour visualiser un calcul cholédocien, et sont-ils réalisés en première intention ?","a":"<div class=\"notion-course\"><p>Les meilleurs examens pour voir un calcul cholédocien sont la <strong><span class=\"nc-blue nc-bold\">bili-IRM</span></strong> et l'<strong><span class=\"nc-blue nc-bold\">écho-endoscopie</span></strong>. Cependant, <span class=\"nc-red nc-bold\">ils ne sont </span><strong><span class=\"nc-red nc-bold\">PAS utilisés en première intention</span></strong>.</p></div>"},{"i":"3aea3e5363c4","n":277,"o":"277-16","u":"Diagnostic positif","t":"Savoir diagnostiquer une lithiase vésiculaire compliquée : cholécystite aiguë","q":"Quels sont les marqueurs biologiques clés et les anomalies échographiques en faveur du diagnostic de cholécystite aiguë ?","a":"<div class=\"notion-course\"><ul><li><strong>Biologie :</strong><ul><li>Un <span style=\"text-decoration:underline;\"><span class=\"nc-blue_bg\">syndrome inflammatoire</span></span> est présent, avec une <span style=\"text-decoration:underline;\">hyperleucocytose à PNN</span> (polynucléaires neutrophiles), une <span style=\"text-decoration:underline;\">élévation de la CRP</span> et/ou de la procalcitonine (PCT).</li><li>Le <span style=\"text-decoration:underline;\">bilan hépatique est habituellement normal</span>.</li><li>La <span style=\"text-decoration:underline;\">lipase est normale</span>.</li></ul></li><li><strong>Échographie :</strong><ul><li>Un <span style=\"text-decoration:underline;\">épaississement de la paroi vésiculaire</span> <span style=\"text-decoration:underline;\">supérieur à 4 mm</span>, souvent en <span class=\"nc-red nc-bold\">triple</span> <span class=\"nc-red nc-bold\">feuillet</span>.</li><li>Une <span style=\"text-decoration:underline;\">distension vésiculaire</span> <span style=\"text-decoration:underline;\">supérieure à 4 cm</span>.</li><li>La présence d'un ou plusieurs <span style=\"text-decoration:underline;\">calculs vésiculaires</span> (hyperéchogènes, mobiles, avec cône d'ombre postérieur).</li><li>Un <span style=\"text-decoration:underline;\">signe de <span class=\"nc-green nc-bold\">Murphy</span> échographique</span> positif, caractérisé par une douleur provoquée lors de la compression de la vésicule par la sonde d'échographie.</li></ul></li></ul></div>"},{"i":"68d635c2b77e","n":277,"o":"277-16","u":"Diagnostic positif","t":"Savoir diagnostiquer une lithiase vésiculaire compliquée : cholécystite aiguë","q":"Quels sont les signes cliniques majeurs permettant de suspecter une cholécystite aiguë ?","a":"<div class=\"notion-course\"><ul><li>Une <span style=\"text-decoration:underline;\"><span class=\"nc-orange_bg\">colique hépatique</span> persistante</span>, d'une durée <span style=\"text-decoration:underline;\">supérieure à 6 heures</span>, souvent même <span style=\"text-decoration:underline;\">supérieure à 24 heures</span>.</li><li>Un <span style=\"text-decoration:underline;\"><span class=\"nc-blue_bg\">syndrome infectieux</span> fréquent</span>, caractérisé par de la <span style=\"text-decoration:underline;\"><span class=\"nc-blue_bg nc-bold\">fièvre</span></span> et des <span style=\"text-decoration:underline;\">frissons</span>.</li><li>L'<span style=\"text-decoration:underline;\">absence d'<span class=\"nc-yellow_bg\">ictère</span></span>, sauf en cas de syndrome de Mirizzi, atypique.</li><li>Des <span style=\"text-decoration:underline;\">signes d'irritation péritonéale locaux</span> sont possibles, notamment en cas de cholécystite grave.</li></ul></div>"},{"i":"f7c6db333207","n":277,"o":"277-16","u":"Diagnostic positif","t":"Savoir diagnostiquer une lithiase vésiculaire compliquée : cholécystite aiguë","q":"Quel est le mécanisme physiopathologique de la cholécystite aiguë lithiasique ?","a":"<div class=\"notion-course\"><p>La cholécystite aiguë lithiasique est causée par l'<span style=\"text-decoration:underline;\"><span class=\"nc-yellow_bg\">obstruction prolongée du canal cystique par un calcul</span></span>. Cette obstruction entraîne une inflammation de la paroi vésiculaire, pouvant évoluer vers une <span class=\"nc-purple nc-bold\">infection aiguë</span> de la vésicule biliaire.</p></div>"},{"i":"0318d655c6b4","n":277,"o":"277-17","u":"Examens complémentaires","t":"Connaître l’indication des examens d’imagerie devant une cholécystite aiguë","q":"Quels sont les signes échographiques évocateurs d'une cholécystite aiguë ?","a":"<div class=\"notion-course\"><ul><li><strong>Épaississement de la paroi</strong> de la vésicule biliaire, mesurant <strong>plus de 4 mm</strong>, et d'aspect en <strong><span class=\"nc-red nc-bold\">triple</span> <span class=\"nc-red nc-bold\">feuillet</span></strong>.</li><li><strong>Distension</strong> de la vésicule biliaire, avec un diamètre supérieur à <strong>4 cm</strong>.</li><li>Présence d'un <strong>Murphy échographique</strong> (douleur déclenchée par la sonde d'<span class=\"nc-blue nc-bold\">échographie</span> au niveau de la vésicule biliaire).</li></ul></div>"},{"i":"2d5af5681730","n":277,"o":"277-17","u":"Examens complémentaires","t":"Connaître l’indication des examens d’imagerie devant une cholécystite aiguë","q":"Dans quelles situations un scanner abdominal est-il envisagé devant une cholécystite aiguë ?","a":"<div class=\"notion-course\"><p>Le <span class=\"nc-blue_bg\">scanner abdominal</span> est envisagé en seconde intention dans les situations suivantes :</p><ul><li>En cas de <strong>doute diagnostique</strong>.</li><li>Pour rechercher ou évaluer des <strong>complications</strong> de la cholécystite aiguë.</li><li>En cas de <strong>contre-indication chirurgicale</strong>, pour une meilleure planification thérapeutique ou recherche d'alternatives non chirurgicales.</li></ul></div>"},{"i":"a9f70cc8e775","n":277,"o":"277-17","u":"Examens complémentaires","t":"Connaître l’indication des examens d’imagerie devant une cholécystite aiguë","q":"Quel est l'examen d'imagerie de première intention à réaliser devant une suspicion de cholécystite aiguë ?","a":"<div class=\"notion-course\"><p>L'examen d'imagerie de <span class=\"nc-red nc-bold\">première intention</span> est <span class=\"nc-blue nc-bold\">l'</span><strong><span class=\"nc-blue nc-bold\">échographie abdominale</span></strong>.</p></div>"},{"i":"577ad3f56ef7","n":277,"o":"277-20","u":"Prise en charge","t":"Connaître les principes du traitement de la cholécystite aiguë","q":"Quel est le traitement chirurgical de la cholécystite aiguë et dans quel délai doit-il être réalisé ?","a":"<div class=\"notion-course\"><ul><li>La <span class=\"nc-pink nc-bold\">cholécystectomie</span> laparoscopique précoce au cours de la <span class=\"nc-pink nc-bold\">même hospitalisation</span> est privilégiée quand elle est réalisable. Dépasser 72 heures ne conduit pas automatiquement à attendre six semaines.</li></ul></div>"},{"i":"c62c563eba47","n":277,"o":"277-20","u":"Prise en charge","t":"Connaître les principes du traitement de la cholécystite aiguë","q":"Quelle est l'antibiothérapie recommandée pour la cholécystite aiguë et pour quelle durée ?","a":"<div class=\"notion-course\"><ul><li>Antibiothérapie selon gravité, acquisition, écologie et allergies, puis adaptation aux prélèvements. La durée dépend de la complication et du contrôle de foyer ; sept jours ne sont pas un schéma universel après <span class=\"nc-pink_bg\">cholécystectomie</span> efficace.</li></ul></div>"},{"i":"e87cb43f8fda","n":277,"o":"277-20","u":"Prise en charge","t":"Connaître les principes du traitement de la cholécystite aiguë","q":"Quelle est la prise en charge symptomatique de la cholécystite aiguë ?","a":"<div class=\"notion-course\"><ul><li>Hospitalisation, antalgiques et correction adaptée des troubles hydroélectrolytiques, avec avis <span class=\"nc-pink_bg\">chirurgical</span> et traitement étiologique. Réévaluer AINS selon rein, risque digestif et contexte infectieux ; ils ne sont pas systématiques.</li></ul></div>"},{"i":"3f28a6acbe4b","n":277,"o":"277-22","u":"Suivi et / ou pronostic","t":"Connaître les complications septiques de la cholécystite aiguë","q":"Quand parle-t-on de péritonite biliaire au cours de l'aggravation d'une cholécystite aiguë et quelle est sa prise en charge ?","a":"<div class=\"notion-course\"><p>La <span class=\"nc-red nc-bold\">péritonite biliaire</span> survient lorsque l'infection diffuse au péritoine, d'abord de manière localisée puis généralisée. C'est une <strong>urgence chirurgicale absolue</strong>.</p></div>"},{"i":"651f18111e5d","n":277,"o":"277-22","u":"Suivi et / ou pronostic","t":"Connaître les complications septiques de la cholécystite aiguë","q":"Quelle est la première complication septique de la cholécystite aiguë par ordre chronologique d'aggravation ?","a":"<div class=\"notion-course\"><p>La première complication est l'<strong>empyème vésiculaire</strong> ou <strong>pyocholécyste</strong>. Il s'agit d'une vésicule biliaire sous tension remplie de pus, mais encore contenue <span class=\"nc-green_bg\">par</span> sa paroi.</p></div>"},{"i":"8866f1939ae6","n":277,"o":"277-22","u":"Suivi et / ou pronostic","t":"Connaître les complications septiques de la cholécystite aiguë","q":"Quelles sont les complications de la perforation de la paroi vésiculaire au cours d'une cholécystite aiguë ?","a":"<div class=\"notion-course\"><p>La perforation de la paroi vésiculaire peut entraîner un <strong>abcès péri-vésiculaire</strong> ou un <strong><span class=\"nc-red_bg\">abcès hépatique</span> de contiguïté</strong>.</p></div>"},{"i":"fa2fc52f6111","n":277,"o":"277-22","u":"Suivi et / ou pronostic","t":"Connaître les complications septiques de la cholécystite aiguë","q":"Qu'est-ce que la gangrène vésiculaire dans le contexte des complications de la cholécystite aiguë ?","a":"<div class=\"notion-course\"><p>La gangrène vésiculaire est la <strong>nécrose de la paroi vésiculaire</strong>, qui est un signe d'ischémie.</p></div>"},{"i":"2fd43aacbc41","n":277,"o":"277-23","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une lithiase biliaire compliquée : angiocholite aiguë","q":"Que peut révéler l'échographie abdominale en cas d'angiocholite aiguë ?","a":"<div class=\"notion-course\"><p>L'<span class=\"nc-brown_bg\">échographie</span> peut mettre en évidence :</p><ul><li>Une <strong><span class=\"nc-blue_bg\">lithiase vésiculaire</span></strong> (souvent associée).</li><li>Un épaississement de la <strong>paroi de la vésicule</strong>.</li><li>Une <strong><span class=\"nc-yellow_bg\">dilatation de la voie biliaire principale</span></strong> (VBP), bien qu'inconstante.</li><li>Un <strong>calcul de la VBP</strong>, avec une sensibilité de détection de seulement 30 à 50%.</li></ul><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>La triade douleur–<span class=\"nc-blue_bg nc-bold\">fièvre</span>–<span class=\"nc-yellow_bg\">ictère</span> est évocatrice mais inconstante ; son ordre et un délai de 48 heures ne sont pas requis. Une <span class=\"nc-pink nc-bold\">angiocholite</span> grave peut se présenter d’emblée par sepsis ou <span class=\"nc-red nc-bold\">choc</span>.</li></ul></div></div>"},{"i":"6d6ee847861f","n":277,"o":"277-23","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une lithiase biliaire compliquée : angiocholite aiguë","q":"Quelle est l'importance des hémocultures dans le diagnostic de l'angiocholite aiguë et quels germes sont le plus souvent retrouvés ?","a":"<div class=\"notion-course\"><p>Des <strong>hémocultures systématiques</strong> sont réalisées car elles sont souvent positives, révélant la présence de <strong>germes digestifs</strong> (principalement des bacilles Gram négatifs).</p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>La triade douleur–<span class=\"nc-blue_bg nc-bold\">fièvre</span>–<span class=\"nc-yellow_bg\">ictère</span> est évocatrice mais inconstante ; son ordre et un délai de 48 heures ne sont pas requis. Une <span class=\"nc-pink nc-bold\">angiocholite</span> grave peut se présenter d’emblée par sepsis ou <span class=\"nc-red nc-bold\">choc</span>.</li></ul></div></div>"},{"i":"ea885f7943a5","n":277,"o":"277-23","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une lithiase biliaire compliquée : angiocholite aiguë","q":"Quelle est la définition de l'angiocholite aiguë ?","a":"<div class=\"notion-course\"><p>L'<span class=\"nc-red nc-bold\">angiocholite aiguë</span> est une <strong><span class=\"nc-purple_bg\">infection aiguë</span> de la <span class=\"nc-red nc-bold\">voie biliaire principale</span></strong>, le plus souvent causée par l'enclavement <span class=\"nc-yellow_bg\">d'un calcul</span> et des germes digestifs (principalement des <strong>bacilles Gram négatifs</strong>).</p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>La triade douleur–<span class=\"nc-blue_bg nc-bold\">fièvre</span>–<span class=\"nc-yellow_bg\">ictère</span> est évocatrice mais inconstante ; son ordre et un délai de 48 heures ne sont pas requis. Une <span class=\"nc-pink nc-bold\">angiocholite</span> grave peut se présenter d’emblée par sepsis ou <span class=\"nc-red nc-bold\">choc</span>.</li></ul></div></div>"},{"i":"eaf4d0cc5d74","n":277,"o":"277-23","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une lithiase biliaire compliquée : angiocholite aiguë","q":"Quels éléments biologiques sont attendus en cas d'angiocholite aiguë ?","a":"<div class=\"notion-course\"><p>Biologiquement, l'<span class=\"nc-red nc-bold\">angiocholite aiguë</span> se caractérise par :</p><ul><li>Un <strong><span class=\"nc-blue_bg\">syndrome inflammatoire ou infectieux</span></strong>.</li><li>Une <strong><span class=\"nc-yellow_bg\">cholestase ictérique</span></strong> (avec bilirubine à prédominance conjuguée).</li><li>Une <strong><span class=\"nc-blue_bg\">cytolyse hépatique</span></strong>, fréquente en phase aiguë.</li></ul><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>La triade douleur–<span class=\"nc-blue_bg nc-bold\">fièvre</span>–<span class=\"nc-yellow_bg\">ictère</span> est évocatrice mais inconstante ; son ordre et un délai de 48 heures ne sont pas requis. Une <span class=\"nc-pink nc-bold\">angiocholite</span> grave peut se présenter d’emblée par sepsis ou <span class=\"nc-red nc-bold\">choc</span>.</li></ul></div></div>"},{"i":"f8b9271e39c3","n":277,"o":"277-23","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une lithiase biliaire compliquée : angiocholite aiguë","q":"Quels sont les signes cliniques caractéristiques de l'angiocholite aiguë ?","a":"<div class=\"notion-course\"><p>Les signes cliniques sont regroupés dans la <strong>Triade de Charcot</strong>, apparaissant successivement en 48 heures :</p><ul><li>Une <strong><span class=\"nc-blue_bg\">douleur biliaire</span></strong>.</li><li>Une <strong><span class=\"nc-blue_bg nc-bold\">fièvre</span> associée à des frissons</strong> (souvent au premier plan, pouvant être sévère avec <span class=\"nc-red nc-bold\">bactériémie</span> ou <span class=\"nc-red nc-bold\">choc</span>).</li><li>Un <strong><span class=\"nc-yellow_bg\">ictère</span></strong> (<span class=\"nc-yellow_bg\">survient après la douleur</span> ; son absence n'écarte pas le diagnostic).</li></ul><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>La triade douleur–<span class=\"nc-blue_bg nc-bold\">fièvre</span>–<span class=\"nc-yellow_bg\">ictère</span> est évocatrice mais inconstante ; son ordre et un délai de 48 heures ne sont pas requis. Une <span class=\"nc-pink nc-bold\">angiocholite</span> grave peut se présenter d’emblée par sepsis ou <span class=\"nc-red nc-bold\">choc</span>.</li></ul></div></div>"},{"i":"9ea4b6998b98","n":277,"o":"277-24","u":"Examens complémentaires","t":"Connaître l’examen paraclinique de première intention (en urgence) devant une angiocholite","q":"Quel est l'examen paraclinique de première intention en urgence devant une suspicion d'angiocholite aiguë ?","a":"<div class=\"notion-course\"><p><span class=\"nc-blue nc-bold\">L'examen paraclinique</span> de <span class=\"nc-red nc-bold\">première intention</span> en <span class=\"nc-red nc-bold\">urgence</span> devant une <span class=\"nc-red nc-bold\">angiocholite</span> est <span class=\"nc-blue nc-bold\">l'</span><strong><span class=\"nc-blue nc-bold\">échographie abdominale</span></strong>.</p></div>"},{"i":"ae734e92dc79","n":277,"o":"277-24","u":"Examens complémentaires","t":"Connaître l’examen paraclinique de première intention (en urgence) devant une angiocholite","q":"Que permet de rechercher l'échographie abdominale en cas d'angiocholite aiguë ?","a":"<div class=\"notion-course\"><p><span class=\"nc-blue nc-bold\">L'échographie abdominale</span> recherche une <strong><span class=\"nc-blue nc-bold\">lithiase</span> biliaire</strong> et une éventuelle <strong><span class=\"nc-yellow_bg\">dilatation de la voie biliaire principale</span> (VBP)</strong>, bien que cette dernière soit inconstante.</p></div>"},{"i":"640a66bb5271","n":277,"o":"277-25","u":"Identifier une urgence","t":"Connaître les trois évolutions possibles de l’angiocholite","q":"Quelle est l'évolution grave de l'angiocholite aigüe caractérisée par une collection purulente dans le foie ?","a":"<div class=\"notion-course\"><p>L'évolution grave de l'<span class=\"nc-red nc-bold\">angiocholite aigüe</span> caractérisée par une collection purulente intrahépatique est l'<strong><span class=\"nc-red_bg\">abcès hépatique</span></strong>.</p></div>"},{"i":"658f066cb62b","n":277,"o":"277-25","u":"Identifier une urgence","t":"Connaître les trois évolutions possibles de l’angiocholite","q":"Quelles sont les trois évolutions/complications graves de l'angiocholite aigüe, au-delà du simple tableau d'infection biliaire ?","a":"<div class=\"notion-course\"><p>Les trois évolutions ou complications graves de l'<span class=\"nc-red nc-bold\">angiocholite aigüe</span> sont :</p><ul><li>L'<strong><span class=\"nc-red_bg\">abcès hépatique</span></strong>.</li><li>Le <strong>choc <span class=\"nc-red nc-bold\">septique</span></strong> et la <strong>défaillance multiviscérale</strong>.</li><li>L'<strong>angiocholite ictéro-urémigène</strong> (associée à une <span class=\"nc-orange nc-bold\">insuffisance rénale</span> aigüe).</li></ul></div>"},{"i":"662d00bf3ecb","n":277,"o":"277-25","u":"Identifier une urgence","t":"Connaître les trois évolutions possibles de l’angiocholite","q":"Quel terme désigne spécifiquement l'angiocholite aigüe compliquée d'une insuffisance rénale aigüe ?","a":"<div class=\"notion-course\"><p>L'<span class=\"nc-red nc-bold\">angiocholite aigüe</span> associée à une <span class=\"nc-orange nc-bold\">insuffisance rénale</span> aigüe est appelée <strong>angiocholite ictéro-urémigène</strong>.</p></div>"},{"i":"3a41a7c1c735","n":277,"o":"277-26","u":"Prise en charge","t":"Connaître le traitement en cas de sepsis sévère ou choc septique lors d’une angiocholite","q":"Comment doit être réalisée la désobstruction de la VBP en urgence face à une angiocholite avec sepsis sévère ou choc septique ?","a":"<div class=\"notion-course\"><p>La désobstruction de la VBP doit être réalisée en <span class=\"nc-green_bg\">urgence</span> :</p><ul><li>En <span class=\"nc-red nc-bold\">première intention</span>, par <strong>CPRE</strong> (Cholangiopancréatographie Rétrograde Endoscopique).</li><li>Si la CPRE n'est pas disponible en urgence ou si le patient est instable, un <strong>drainage transcutané des voies biliaires</strong> peut être envisagé.</li></ul></div>"},{"i":"85cc8d25c396","n":277,"o":"277-26","u":"Prise en charge","t":"Connaître le traitement en cas de sepsis sévère ou choc septique lors d’une angiocholite","q":"Comment coordonner les traitements d’une angiocholite avec choc ou défaillance d’organe ?","a":"<div class=\"notion-course\"><ul><li>Angiocholite : antibiothérapie IV, hémocultures si possible sans retard, réanimation et contrôle de l’obstacle biliaire. Ces mesures sont engagées en parallèle.</li><li>Drainage biliaire habituellement endoscopique par CPRE ; l’urgence est accrue en cas de choc ou de défaillance d’organe. Ne pas attendre la fin d’une réanimation prolongée ou tous les examens pour organiser le drainage.</li></ul></div>"},{"i":"fb7618a398be","n":277,"o":"277-26","u":"Prise en charge","t":"Connaître le traitement en cas de sepsis sévère ou choc septique lors d’une angiocholite","q":"Quelle est la priorité de prise en charge en cas d'angiocholite avec sepsis sévère ou choc septique ?","a":"<div class=\"notion-course\"><ul><li>Angiocholite : antibiothérapie IV, hémocultures si possible sans retard, réanimation et contrôle de l’obstacle biliaire. Ces mesures sont engagées en parallèle.</li><li>Drainage biliaire habituellement endoscopique par CPRE ; l’urgence est accrue en cas de choc ou de défaillance d’organe. Ne pas attendre la fin d’une réanimation prolongée ou tous les examens pour organiser le drainage.</li></ul></div>"},{"i":"16f119786968","n":277,"o":"277-9","u":"Diagnostic positif","t":"Connaître les caractéristiques de la douleur biliaire","q":"Quels signes sont absents lors d'une colique hépatique simple et signeraient une complication de la lithiase biliaire ?","a":"<div class=\"notion-course\"><p>Une <span class=\"nc-orange_bg\">colique hépatique</span> simple ne comporte <strong><span class=\"nc-red nc-bold\">JAMAIS</span> de <span class=\"nc-red\">fièvre</span> ni d'<span class=\"nc-red\">ictère</span></strong>. Leur présence doit faire évoquer une complication type <strong>cholécystite</strong> ou <strong>angiocholite</strong>.</p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Un signe de <span class=\"nc-green nc-bold\">Murphy</span> évoque surtout une inflammation vésiculaire ; sa présence ne suffit pas à caractériser une <span class=\"nc-orange_bg\">colique hépatique</span> simple. Une paroi épaissie n’est pas spécifique et s’interprète avec douleur, <span class=\"nc-red\">fièvre</span> et imagerie.</li></ul></div></div>"},{"i":"80d4d93bfbb7","n":277,"o":"277-9","u":"Diagnostic positif","t":"Connaître les caractéristiques de la douleur biliaire","q":"Comment définir la colique hépatique dans le contexte de la lithiase biliaire ?","a":"<div class=\"notion-course\"><p>La <span class=\"nc-orange_bg\">colique hépatique</span> est la manifestation douloureuse d'un <strong><span class=\"nc-yellow_bg\">blocage</span> <span class=\"nc-yellow_bg nc-bold\">transitoire</span></strong> du calcul dans les voies biliaires.</p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Un signe de <span class=\"nc-green nc-bold\">Murphy</span> évoque surtout une inflammation vésiculaire ; sa présence ne suffit pas à caractériser une <span class=\"nc-orange_bg\">colique hépatique</span> simple. Une paroi épaissie n’est pas spécifique et s’interprète avec douleur, <span class=\"nc-red\">fièvre</span> et imagerie.</li></ul></div></div>"},{"i":"8d7506c22338","n":277,"o":"277-9","u":"Diagnostic positif","t":"Connaître les caractéristiques de la douleur biliaire","q":"Quelles sont les caractéristiques sémiologiques de la douleur biliaire (colique hépatique) ?","a":"<div class=\"notion-course\"><ul><li>Type : <strong>brutale</strong>, <strong>intense</strong>, continue, à type de <span class=\"nc-orange nc-bold\">broiement</span> ou <span class=\"nc-orange nc-bold\">crampe</span>.</li><li>Localisation : <strong>épigastrique</strong> ou <strong>hypochondre droit</strong>.</li><li>Durée : généralement <strong>inférieure à 6 heures</strong>.</li><li>Irradiation : en hémi-ceinture vers l'<strong>épaule</strong> ou l'<strong>omoplate droite</strong>.</li><li>Signes associés : <strong><span class=\"nc-pink nc-bold\">inhibition de la respiration</span></strong>, nausées, vomissements.</li><li>Signe spécifique : <strong>Signe de <span class=\"nc-green nc-bold\">Murphy</span></strong>.</li></ul><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Un signe de <span class=\"nc-green nc-bold\">Murphy</span> évoque surtout une inflammation vésiculaire ; sa présence ne suffit pas à caractériser une <span class=\"nc-orange_bg\">colique hépatique</span> simple. Une paroi épaissie n’est pas spécifique et s’interprète avec douleur, <span class=\"nc-red\">fièvre</span> et imagerie.</li></ul></div></div>"},{"i":"f2730f8cfaf6","n":277,"o":"277-2","u":"Epidémiologie","t":"Connaître l’incidence de la pathologie lithiasique biliaire, la fréquence de survenue de symptômes et les indications de dépistage.","q":"Quels sont les points essentiels concernant l’incidence de la pathologie lithiasique biliaire, la fréquence de survenue de symptômes et les indications de dépistage. ?","a":"<div class=\"notion-course\"><p>La <span><span class=\"nc-blue_bg\">lithiase vésiculaire</span></span> touche <span>20 %</span> de la population générale, et jusqu’à <span><span class=\"nc-pink nc-bold\">60 %</span></span><span class=\"nc-pink nc-bold\"> à </span><span><span class=\"nc-pink nc-bold\">80 ans</span></span> (<span>prévalence croissante avec l’âge</span>).</p>\n      <ul>\n        <li><span>Asymptomatique</span> dans <span>80 %</span> des cas</li>\n        <li><span>Symptomatique</span> dans <span>20 %</span> des cas</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong><span><span class=\"nc-green nc-bold\">Dépistage</span></span>.</strong> Le <span class=\"nc-green nc-bold\">dépistage</span> de la <span><span class=\"nc-blue_bg\">lithiase vésiculaire</span></span> <span>n’est PAS indiqué</span> chez le sujet <span class=\"nc-orange nc-bold\">asymptomatique</span>.</div></div>"},{"i":"7982723f5e9c","n":277,"o":"277-3","u":"Epidémiologie","t":"Connaître la fréquence des complications de la lithiase biliaire","q":"Quels sont les points essentiels concernant la fréquence des complications de la lithiase biliaire ?","a":"<div class=\"notion-course\"><p>Parmi <span>les</span> sujets <span>symptomatiques</span>, la probabilité cumulée de complication est faible : <span>5 %</span> des sujets symptomatiques développent une complication (<span>cholécystite</span>, <span>migration</span>, <span>angiocholite</span>, <span>pancréatite</span>).</p>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> La grande majorité des <span>lithiases vésiculaires</span> reste <span>silencieuse</span> ; le risque évolutif ne concerne qu’une minorité de patients devenus symptomatiques.</div></div>"},{"i":"f33f28b2bcc8","n":277,"o":"277-4","u":"Epidémiologie","t":"Connaître les caractéristiques des calculs et les facteurs de risque de calculs cholestéroliques et pigmentaires","q":"Quels sont les points essentiels concernant les caractéristiques des calculs et les facteurs de risque de calculs cholestéroliques et pigmentaires ?","a":"<div class=\"notion-course\"><p>Deux grands types de calculs, de fréquence et de mécanisme distincts :</p>\n      <table>\n        <thead><tr><th></th><th>Calculs cholestéroliques</th><th>Lithiase p<span>igm</span>entaire</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Fréquence</strong></td><td><span>80 %</span></td><td><span>20 %</span></td></tr>\n          <tr>\n            <td><strong>Mécanisme</strong></td>\n            <td>Augmentation de la concentration biliaire en <span>cholestérol</span> ; sursaturation → nucléation → précipitation</td>\n            <td><span>Déconjugaison de la bilirubine</span> qui devient insoluble (la <span>bilirubine</span> conjuguée est soluble, la non-conjuguée est insoluble)</td>\n          </tr>\n          <tr>\n            <td><strong><span>Facteurs de risque</span></strong></td>\n            <td>\n              <strong>Âge :</strong> <span><span class=\"nc-pink nc-bold\">&gt; 50-65 ans</span></span> ; <span>ATCD familiaux</span><br>\n              <strong>Femme :</strong> <span><span class=\"nc-pink_bg\">sexe féminin</span></span> ; <span><span class=\"nc-pink_bg\">multiparité</span></span> ; <span><span class=\"nc-pink_bg\">grossesse</span></span><br>\n              <strong>Pondéral :</strong> <span><span class=\"nc-orange_bg\">surpoids/obésité</span></span> ; <span>variations importantes de poids</span><br>\n              <strong>Digestif :</strong> <span><span class=\"nc-blue_bg\">jeûne prolongé</span></span> ; <span><span class=\"nc-blue_bg\">nutrition parentérale</span></span> ; ATCD de <span>gastrectomie ou bypass</span><br>\n              <strong>Médicaments :</strong> <span>œstrogènes</span> ; <span><span class=\"nc-pink nc-bold\">fibrates</span></span> ; <span>analogues de la somatostatine</span>\n            </td>\n            <td>\n              <strong><span class=\"nc-orange_bg\">Hémolyse</span> :</strong> <span><span class=\"nc-orange_bg\">drépanocytose</span></span> ; <span><span class=\"nc-orange_bg\">thalassémie</span></span> (augmentation de la production de <span>bilirubine</span>)<br>\n              <strong><span>Infectieux</span> :</strong> <span><span class=\"nc-red_bg\">infections biliaires chroniques</span></span><br>\n              <strong>Obstacle :</strong> <span>sténose bénigne/maligne de la VBP</span>\n            </td>\n          </tr>\n        </tbody>\n      </table></div>"},{"i":"34062c7120e5","n":277,"o":"277-7","u":"Physiopathologie","t":"Connaître les trois complications de la pathologie lithiasique vésiculaire et leur mécanisme","q":"Quels sont les points essentiels concernant les trois complications de la pathologie lithiasique vésiculaire et leur mécanisme ?","a":"<div class=\"notion-course\"><p><span class=\"nc-red nc-bold\">Trois complications</span> principales selon le niveau et la durée du blocage :</p>\n      <table>\n        <thead><tr><th>Complication</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-orange_bg\">Colique hépatique</span></span></td><td><span class=\"nc-yellow_bg\">Blocage</span> <span><span class=\"nc-yellow_bg nc-bold\">transitoire</span></span> <span class=\"nc-yellow_bg\">d’un calcul</span> (<span class=\"nc-purple nc-bold\">canal cystique</span> ou VBP) → <span>mise en tension brutale des voies biliaires</span></td></tr>\n          <tr><td><span>Cholécystite aiguë</span></td><td><span><span class=\"nc-red nc-bold\">Obstruction prolongée du canal cystique</span></span> → inflammation puis <span>infection</span> de la <span>vésicule</span></td></tr>\n          <tr><td><span>Migration lithiasique</span> (vers la VBP)</td><td>Passage d’un <span class=\"nc-blue_bg\">calcul dans la VBP</span> → peut se compliquer de <span>lithiase de la VBP</span>, <span>angiocholite</span> ou <span>pancréatite aiguë</span></td></tr>\n        </tbody>\n      </table></div>"},{"i":"64f0a4800b71","n":277,"o":"277-8","u":"Physiopathologie","t":"Connaître la physiopathologie de la lithiase cholestérolique et de la lithiase pigmentaire","q":"Quels sont les points essentiels concernant la physiopathologie de la lithiase cholestérolique et de la lithiase pigmentaire ?","a":"<div class=\"notion-course\"><table>\n        <thead><tr><th>Type</th><th><span>Physiopathologie</span></th></tr></thead>\n        <tbody>\n          <tr><td><span>Lithiase cholestérolique</span></td><td>Augmentation de la concentration biliaire en <span>cholestérol</span> (causée par <span>les</span> FR) → <span>sursaturation</span> → <span>nucléation</span> → <span>précipitation lithiasique</span></td></tr>\n          <tr><td><span>Lithiase pigmentaire</span></td><td><span>Déconjugaison de la bilirubine</span> qui devient insoluble : la <span>bilirubine conjuguée est soluble, la non-conjuguée est insoluble</span> → précipitation</td></tr>\n        </tbody>\n      </table></div>"},{"i":"9490b06c8dca","n":277,"o":"277-11","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic positif de la lithiase vésiculaire symptomatique simple","q":"Quels sont les points essentiels concernant les éléments du diagnostic positif de la lithiase vésiculaire symptomatique simple ?","a":"<div class=\"notion-course\"><p>Le diagnostic de <span><span class=\"nc-blue_bg\">lithiase vésiculaire</span></span> symptomatique simple repose sur un faisceau clinico-<span>biologique</span>-échographique :</p>\n      <table>\n        <thead><tr><th>Axe</th><th>Éléments</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Clinique</strong></td><td><span><span class=\"nc-orange_bg\">Colique hépatique</span></span> <span>&lt; 6 h</span> ; <span>pas de <span class=\"nc-red\">fièvre</span></span> ; <span><span class=\"nc-green_bg\">pas d’ictère</span></span> ; signe de <span><span class=\"nc-green nc-bold\">Murphy</span></span></td></tr>\n          <tr><td><strong>Biologie</strong></td><td>Aucune anomalie : <span><span class=\"nc-green_bg\">bilan hépatique normal</span></span> ; <span>pas de <span class=\"nc-blue_bg\">syndrome inflammatoire</span></span> (sauf si <span class=\"nc-red nc-bold\">migration lithiasique</span> associée)</td></tr>\n          <tr><td><strong><span>Échographie</span></strong></td><td>Calculs vésiculaires : <span>hyperéchogènes</span> ; <span>cône d’ombre postérieur</span> ; <span>mobiles</span> avec le patient (<span>Se 95 %</span>, meilleure que <span>TDM</span>/<span>IRM</span>). Ne pas confondre avec le <span>sludge</span> (bile épaisse)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> Le <span>sludge</span> (boue biliaire) est hyperéchogène mais SANS cône d’ombre et déclive — à ne pas prendre pour un calcul.</div></div>"},{"i":"5abb8d7ac15b","n":277,"o":"277-18","u":"Contenu multimédia","t":"Bili-IRM d’un empierrement cholédocien","q":"Quels sont les points essentiels concernant bili-IRM d’un empierrement cholédocien ?","a":"<div class=\"notion-course\"><p>La <strong><span><span class=\"nc-blue nc-bold\">bili-IRM</span></span></strong> (<span class=\"nc-blue_bg\">cholangio-</span><span><span class=\"nc-blue_bg\">IRM</span></span>) est, avec l’<span><span class=\"nc-blue nc-bold\">écho-endoscopie</span></span>, le meilleur examen pour mettre en évidence des calculs de la <span class=\"nc-red nc-bold\">voie biliaire principale</span> (<span>Se &gt; 90 %</span>). Un <strong><span class=\"nc-red nc-bold\">empierrement cholédocien</span></strong> correspond à de <span>multiples calculs occupant la VBP</span>.</p>\n      <table>\n        <thead><tr><th>Élément sémiologique</th><th>Aspect <span>bili-IRM</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong>Voie biliaire principale</strong></td><td><span>Hypersignal T2</span> intense (la bile statique en T2 brille)</td></tr>\n          <tr><td><strong>Calculs cholédociens</strong></td><td><span>Images hypointenses en T2</span> (« defects ») au sein du conduit hypersignal — <span>absence de rehaussement</span> après injection</td></tr>\n          <tr><td><strong>Anatomie analysable</strong></td><td>Conduit hépatique droit, gauche, cystique, cholédoque — utile pour le bilan pré-<span>CPRE</span></td></tr>\n          <tr><td><strong>Empierrement</strong></td><td><span>Multiples defects</span> alignés dans la VBP, avec dilatation d’amont</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Mémo signal.</strong> En T2 : la <span>bile = blanche</span>, <span>les</span> <span>calculs = noirs</span>. Tout point noir dans un <span class=\"nc-yellow_bg nc-bold\">canal</span> blanc et dilaté = calcul jusqu’à preuve du contraire.</div>\n      </div>"},{"i":"2fbce448bbcf","n":277,"o":"277-19","u":"Contenu multimédia","t":"Aspect échographique d’une cholécystite aiguë","q":"Quels sont les points essentiels concernant aspect échographique d’une cholécystite aiguë ?","a":"<div class=\"notion-course\"><p><strong>Signes diagnostiques principaux</strong> (faisceau d’arguments) :</p>\n      <ul>\n        <li>Paroi vésiculaire <span>épaissie <span class=\"nc-yellow_bg nc-bold\">&gt; 4 mm</span></span>, aspect en <span><span class=\"nc-red nc-bold\">triple</span> <span class=\"nc-red nc-bold\">feuillet</span></span></li>\n        <li><span>Distension vésiculaire</span> (<span>&gt; 4 cm</span>)</li>\n        <li>Calcul vésiculaire <span>hyperéchogène</span>, mobile, avec <span>cône d’ombre postérieur</span></li>\n      </ul>\n      <p><strong>Autres signes</strong> (non indispensables au diagnostic, mais utiles) :</p>\n      <ul>\n        <li><span>Signe de <span class=\"nc-green nc-bold\">Murphy</span> échographique</span> — douleur au passage de la sonde sur la <span>vésicule</span></li>\n        <li><span>Sludge intra-vésiculaire</span> — bile épaisse hyperéchogène déclive, <span>sans cône d’ombre</span> (à distinguer du calcul)</li>\n        <li><span>Épanchement péri-vésiculaire</span> — <span>signe de gravité</span></li>\n      </ul>\n      </div>"},{"i":"4e5b6f0d4fd1","n":277,"o":"277-21","u":"Prise en charge","t":"Connaître le délai de prise en charge chirurgicale de la cholécystite","q":"Quels sont les points essentiels concernant le délai de prise en charge chirurgicale de la cholécystite ?","a":"<div class=\"notion-course\"><ul><li>Cholécystite aiguë lithiasique : hospitalisation, antalgiques, correction des troubles hydro-électrolytiques, antibiothérapie selon gravité et contexte, avis chirurgical.</li><li>La <span class=\"nc-pink nc-bold\">cholécystectomie</span> laparoscopique précoce au cours de la <span class=\"nc-pink nc-bold\">même hospitalisation</span> est privilégiée quand elle est réalisable. Dépasser 72 heures ne conduit pas automatiquement à attendre six semaines.</li><li>Défaillance d’organe ou risque opératoire élevé : réanimation et discussion multidisciplinaire du contrôle de foyer, parfois drainage vésiculaire. La durée d’antibiothérapie dépend de la complication et de l’efficacité du contrôle du foyer.</li></ul></div>"},{"i":"461806b5fac2","n":277,"o":"277-27","u":"Prise en charge","t":"Connaître les deux principes du traitement de l’angiocholite aiguë et les modalités de la cholangiopancréatographie rétrograde endoscopique (CPRE)","q":"Quels sont les points essentiels concernant les deux principes du traitement de l’angiocholite aiguë et les modalités de la cholangiopancréatographie rétrograde endoscopique (CPRE) ?","a":"<div class=\"notion-course\"><p><strong>Deux principes :</strong></p>\n      <ul>\n        <li><strong><span>Antibiothérapie</span> :</strong> <span><span class=\"nc-pink_bg\">amoxicilline-acide clavulanique</span></span> ou <span><span class=\"nc-pink_bg\">C3G + imidazolé</span></span> pendant <span><span class=\"nc-pink nc-bold\">7 jours</span></span> (+ traitement symptomatique)</li>\n        <li><strong>Désobstruction de la VBP en <span><span class=\"nc-red nc-bold\">urgence</span></span> (<span><span class=\"nc-pink nc-bold\">&lt; 24 h</span></span>) :</strong> <span>CPRE</span> en 1ʳᵉ intention ; <span>drainage transcutané</span> si <span>CPRE</span> non disponible ou <span class=\"nc-red nc-bold\">patient instable</span></li>\n      </ul>\n      <p><strong>Modalités de la <span>CPRE</span></strong> (geste endoscopique sous AG) :</p>\n      <table>\n        <thead><tr><th>Item</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Déroulement</strong></td><td>Abord de la VBP ; <span><span class=\"nc-pink_bg\">sphinctérotomie endoscopique</span></span><span class=\"nc-pink_bg\"> du sphincter d’Oddi</span> ; <span class=\"nc-pink_bg\">extraction instrumentale du calcul</span></td></tr>\n          <tr><td><strong>Complications</strong> (<span>5-10 %</span>)</td><td><span><span class=\"nc-red_bg\">Pancréatite aiguë</span></span> (<span>5 %</span>, liée au PDC) ; <span><span class=\"nc-red nc-bold\">hémorragie</span></span> (<span>1 %</span>) ; <span><span class=\"nc-red nc-bold\">infection</span></span> ; <span><span class=\"nc-red nc-bold\">perforation</span> <span class=\"nc-red nc-bold\">duodénale</span></span> (<span>0,1-0,6 %</span>)</td></tr>\n          <tr><td><strong>Inconvénients</strong></td><td>Examen coûteux, invasif ; n’est plus réalisée à visée purement diagnostique</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong><span class=\"nc-pink nc-bold\">Cholécystectomie</span> (après désobstruction).</strong> <span><span class=\"nc-green_bg\">Angiocholite</span></span><span class=\"nc-green_bg\"> non sévère</span> → durant la <span><span class=\"nc-pink nc-bold\">même hospitalisation</span></span> ; <span class=\"nc-red_bg\">angiocholite sévère</span> → <span class=\"nc-pink nc-bold\">à distance</span>, <span><span class=\"nc-pink nc-bold\">&gt; 1 mois</span></span> ; <span class=\"nc-pink nc-bold\">parfois </span><span><span class=\"nc-pink nc-bold\">non réalisée</span></span> selon le <span>terrain</span> du malade (comorbidités, âge physiologique).</div><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>La CPRE est principalement thérapeutique. Elle expose notamment à pancréatite, <span class=\"nc-red nc-bold\">hémorragie</span>, <span class=\"nc-red nc-bold\">infection</span> et <span class=\"nc-red nc-bold\">perforation</span> ; prévention de la pancréatite par AINS rectal en l’absence de contre-indication et mesures techniques selon le risque.</li></ul></div></div>"},{"i":"f250ec5302b1","n":277,"o":"277-28","u":"Examens complémentaires","t":"Connaître les examens paracliniques pouvant être réalisés à la recherche d’un calcul de la voie biliaire principale (VBP)","q":"Quels sont les points essentiels concernant les examens paracliniques pouvant être réalisés à la recherche d’un calcul de la voie biliaire principale (VBP) ?","a":"<div class=\"notion-course\"><table>\n        <thead><tr><th>Examen</th><th>Performance</th></tr></thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-brown_bg\">Échographie</span></span></td><td>1ʳᵉ intention mais <span>peu sensible</span> pour le calcul cholédocien (<span>Se 30-50 %</span>) ; montre la <span>dilatation de la VBP</span></td></tr>\n          <tr><td><span>Bili-IRM (<span class=\"nc-blue_bg\">cholangio-IRM</span>)</span></td><td>Très sensible (<span>Se &gt; 90 %</span>)</td></tr>\n          <tr><td><span><span class=\"nc-blue nc-bold\">Écho-endoscopie</span></span></td><td>Très sensible (<span>Se &gt; 90 %</span>)</td></tr>\n          <tr><td><span><span class=\"nc-blue_bg\">Cholangiographie per-opératoire</span></span></td><td>Examen sensible ; réalisée pendant la <span class=\"nc-pink nc-bold\">cholécystectomie</span></td></tr>\n          <tr><td><span><span class=\"nc-blue_bg nc-bold\">TDM</span></span></td><td>Valeur diagnostique <span>inférieure</span> à la <span class=\"nc-blue nc-bold\">bili-</span><span><span class=\"nc-blue nc-bold\">IRM</span></span> et à l’<span><span class=\"nc-blue nc-bold\">écho-endoscopie</span></span></td></tr>\n        </tbody>\n      </table></div>"},{"i":"bfeb76960999","n":277,"o":"277-29","u":"Prise en charge","t":"Connaître les deux traitements possibles pour désobstruer la VBP en dehors de l’urgence septique","q":"Quels sont les points essentiels concernant les deux traitements possibles pour désobstruer la VBP en dehors de l’urgence septique ?","a":"<div class=\"notion-course\"><p><span>Lithiase de la VBP</span> <span>sans angiocholite ni pancréatite</span> — deux options de désobstruction :</p>\n      <ul>\n        <li><strong><span class=\"nc-pink_bg\">Désobstruction chirurgicale en 1 temps</span> :</strong> <span><span class=\"nc-pink_bg\">cholécystectomie</span></span><span class=\"nc-pink_bg\"> avec </span><span><span class=\"nc-pink_bg\">désobstruction peropératoire de la VBP</span></span></li>\n        <li><strong>Désobstruction endoscopique en 2 temps :</strong> <span><span class=\"nc-pink_bg\">sphinctérotomie endoscopique</span></span><span class=\"nc-pink_bg\"> biliaire</span>, puis <span><span class=\"nc-pink_bg\">cholécystectomie</span></span></li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 278 — <span>Ictère</span></em></p></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/1cb37f85d9418121b295ca6e80dfd82c?pvs=204","reviewedAt":"2026-10-16","batch":"digestive-infectious-50","verification":"reviewed","note":"Relecture et contrôles du lot réalisés. LiSA : copies locales ; ordinateur et format iPad simulé."}};
